183	// ---- SSE decoders ------------------------------------------------------------------------------
184	
185	/// One dispatched SSE event.
186	#[derive(Debug, Clone, PartialEq, Eq)]
187	pub struct Sse {
188	    pub event: Option<String>,
189	    pub data: String,
190	}
191	
192	/// Lines split at CRLF, CR or LF; the last element is the unterminated rest (maybe empty).
193	fn lines(bytes: &[u8]) -> (Vec<&[u8]>, &[u8]) {
194	    let mut out = Vec::new();
195	    let mut start = 0;
196	    let mut i = 0;
197	    while i < bytes.len() {
198	        match bytes[i] {
199	            b'\n' => {
200	                out.push(&bytes[start..i]);
201	                start = i + 1;
202	            }
203	            b'\r' => {
204	                out.push(&bytes[start..i]);
205	                if bytes.get(i + 1) == Some(&b'\n') {
206	                    i += 1;
207	                }
208	                start = i + 1;
209	            }
210	            _ => {}
211	        }
212	        i += 1;
213	    }
214	    (out, &bytes[start..])
215	}
216	
217	/// The `SSEDecoder` of openai-python and anthropic-python: lines split at CR, LF and CRLF, each
218	/// line decoded as strict UTF-8 (a bad byte raises), no BOM handling, a dispatch on a blank line
219	/// whenever an event name, data, an id or a retry was seen (so `event:` without `data:` dispatches
220	/// an empty data string), and no dispatch at the end of the stream without a blank line.
221	/// SOURCE: openai-python 3.40.0, src/openai/_streaming.py SSEDecoder.decode and
222	/// _SSELineDecoder; anthropic-python 2.3.0, src/anthropic/_streaming.py SSEDecoder.
223	pub fn py_events(bytes: &[u8]) -> Result<Vec<Sse>, String> {
224	    let (ls, rest) = lines(bytes);
225	    let mut out = Vec::new();
226	    let (mut event, mut data, mut last_id, mut retry): (Option<String>, Vec<String>, Option<String>, Option<i64>) = (None, Vec::new(), None, None);
227	    for raw in ls {
228	        let line = std::str::from_utf8(raw).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
229	        if line.is_empty() {
230	            if event.as_deref().is_none_or(str::is_empty) && data.is_empty() && last_id.as_deref().is_none_or(str::is_empty) && retry.is_none() {
231	                continue;
232	            }
233	            out.push(Sse {
234	                event: event.take(),
235	                data: data.join("\n"),
236	            });
237	            data.clear();
238	            retry = None;
239	            continue;
240	        }
241	        if line.starts_with(':') {
242	            continue;
243	        }
244	        let (name, value) = match line.find(':') {
245	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
246	            None => (line, ""),
247	        };
248	        match name {
249	            "event" => event = Some(value.to_owned()),
250	            "data" => data.push(value.to_owned()),
251	            "id" if !value.contains('\0') => last_id = Some(value.to_owned()),
252	            "retry" => retry = value.parse().ok().or(retry),
253	            _ => {}
254	        }
255	    }
256	    std::str::from_utf8(rest).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
257	    Ok(out)
258	}
259	
260	/// openai-node's `SSEDecoder` behind `LineDecoder` and a `TextDecoder`: lossy UTF-8 with the BOM
261	/// stripped, lines split at CR, LF and CRLF, `event` and `data` fields only, a dispatch on a blank
262	/// line when an event name or a data line was seen, and a flush of the pending event at the end.
263	/// SOURCE: openai-node <not pinned: modelled only>, src/core/streaming.ts SSEDecoder.
264	pub fn node_events(bytes: &[u8]) -> Vec<Sse> {
265	    let text = String::from_utf8_lossy(bytes);
266	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text);
267	    let (ls, rest) = lines(text.as_bytes());
268	    let mut all: Vec<&[u8]> = ls;
269	    if !rest.is_empty() {
270	        all.push(rest);
271	    }
272	    let mut out = Vec::new();
273	    let (mut event, mut data): (Option<String>, Vec<String>) = (None, Vec::new());
274	    let dispatch = |event: &mut Option<String>, data: &mut Vec<String>, out: &mut Vec<Sse>| {
275	        if event.as_deref().is_none_or(str::is_empty) && data.is_empty() {
276	            return;
277	        }
278	        out.push(Sse {
279	            event: event.take(),
280	            data: data.join("\n"),
281	        });
282	        data.clear();
283	    };
284	    for raw in all {
285	        let line = std::str::from_utf8(raw).expect("lossy text is UTF-8");
286	        if line.is_empty() {
287	            dispatch(&mut event, &mut data, &mut out);
288	            continue;
289	        }
290	        if line.starts_with(':') {
291	            continue;
292	        }
293	        let (name, value) = match line.find(':') {
294	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
295	            None => (line, ""),
296	        };
297	        match name {
298	            "event" => event = Some(value.to_owned()),
299	            "data" => data.push(value.to_owned()),
300	            _ => {}
301	        }
302	    }
303	    dispatch(&mut event, &mut data, &mut out);
304	    out
305	}
306	
307	/// A reference WHATWG SSE splitter, independent of the crate's: (event, data) per record.
308	pub fn records(bytes: &[u8]) -> Vec<(Option<String>, Vec<u8>)> {
309	    let text = String::from_utf8_lossy(bytes);
310	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text).replace("\r\n", "\n").replace('\r', "\n");
311	    let mut out = Vec::new();
312	    let (mut data, mut has, mut event): (Vec<u8>, bool, Option<String>) = (Vec::new(), false, None);
313	    for line in text.split('\n') {
314	        if line.is_empty() {
315	            if has {
316	                data.pop();
317	                if !data.is_empty() {
318	                    out.push((event.take(), std::mem::take(&mut data)));
319	                }
320	            }
321	            data.clear();
322	            has = false;
323	            event = None;
324	            continue;
325	        }
326	        if line.starts_with(':') {
327	            continue;
328	        }
329	        let (name, value) = match line.find(':') {
330	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
331	            None => (line, ""),
332	        };
333	        match name {
334	            "data" => {
335	                data.extend_from_slice(value.as_bytes());
336	                data.push(b'\n');
337	                has = true;
338	            }
339	            "event" => event = Some(value.to_owned()),
340	            _ => {}
341	        }
342	    }
343	    out
344	}
345	
346	pub fn payloads(bytes: &[u8]) -> Vec<Vec<u8>> {
347	    records(bytes).into_iter().map(|(_, d)| d).collect()
348	}
