1159	/// SOURCE: anthropic-python 2.3.0, src/anthropic/lib/streaming/_messages.py
1160	/// accumulate_event; src/anthropic/_streaming.py Stream.__stream__.
1161	pub fn run_anthropic_python(bytes: &[u8]) -> Run {
1162	    let mut snap: Option<Vec<Map<String, Value>>> = None;
