2	//! Fixture replays (spec § 8.3, AC 2, AC 3, AC 5).
3	
4	mod support;
5	
6	use std::path::{Path, PathBuf};
7	
8	use paigasus_gateway_core::{Format, Metric, OnFailure};
9	use support::driver::{DECIDERS, allow_all, block_named, drive, limits};
10	use support::oracle::{check_i1, payloads};
11	
12	const SETS: [(Format, &str); 4] = [
13	    (Format::OpenAiChat, "openai/conforming"),
14	    (Format::OpenAiChat, "openai/malformed"),
15	    (Format::AnthropicMessages, "anthropic/conforming"),
16	    (Format::AnthropicMessages, "anthropic/malformed"),
17	];
18	
19	fn dir(rel: &str) -> PathBuf {
20	    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(rel)
21	}
22	
23	fn files(rel: &str) -> Vec<(String, Vec<u8>)> {
24	    let mut v: Vec<(String, Vec<u8>)> = std::fs::read_dir(dir(rel))
25	        .unwrap_or_else(|e| panic!("{rel}: {e}"))
26	        .map(|e| e.unwrap().path())
27	        .filter(|p| p.extension().is_some_and(|x| x == "sse"))
28	        .map(|p| (p.file_stem().unwrap().to_string_lossy().into_owned(), std::fs::read(&p).unwrap()))
29	        .collect();
30	    v.sort();
31	    assert!(!v.is_empty(), "{rel} holds no fixtures");
32	    v
33	}
34	
35	fn s(b: &[u8]) -> String {
36	    String::from_utf8_lossy(b).into_owned()
37	}
38	
39	/// The CRLF fixture keeps its CR bytes through git (`.gitattributes`).
40	#[test]
41	fn the_crlf_fixture_has_crlf_line_endings() {
42	    let bytes = std::fs::read(dir("openai/conforming/crlf_endings.sse")).unwrap();
43	    assert!(bytes.windows(2).any(|w| w == b"\r\n"), "crlf_endings.sse lost its CR bytes");
44	    assert!(
45	        !bytes.iter().enumerate().any(|(i, b)| *b == b'\n' && (i == 0 || bytes[i - 1] != b'\r')),
46	        "crlf_endings.sse has a bare LF"
47	    );
48	}
49	
50	/// AC 2: with allow-all, every conforming fixture's data payloads come out byte-equal and in order.
51	#[test]
52	fn allow_all_is_payload_identical_for_every_conforming_fixture() {
53	    for (format, rel) in [(Format::OpenAiChat, "openai/conforming"), (Format::AnthropicMessages, "anthropic/conforming")] {
54	        for (name, bytes) in files(rel) {
55	            let o = drive(format, limits(OnFailure::Block), &[&bytes], &allow_all);
56	            assert_eq!(payloads(&o.out), payloads(&bytes), "{rel}/{name}");
57	        }
58	    }
59	}
60	
61	/// AC 3: a blocked call's canary never appears, for every fixture and both on_failure modes
62	/// (except where observe mode passes the stream through by design).
63	#[test]
64	fn blocked_canaries_never_appear() {
65	    let observe_may_leak = ["index_reuse"];
66	    for (format, rel) in SETS {
67	        for (name, bytes) in files(rel) {
68	            let blocked = drive(format, limits(OnFailure::Block), &[&bytes], &block_named);
69	            assert!(!s(&blocked.out).contains("CANARY"), "{rel}/{name} (block):\n{}", s(&blocked.out));
70	            let observed = drive(format, limits(OnFailure::Allow), &[&bytes], &block_named);
71	            if !observe_may_leak.contains(&name.as_str()) {
72	                assert!(!s(&observed.out).contains("CANARY"), "{rel}/{name} (allow):\n{}", s(&observed.out));
73	            }
74	        }
75	    }
76	}
77	
78	/// I1 on every fixture under every decider (see `oracle::check_i1`), and the stream ends. The
79	/// terminal error frame (D17) makes every OpenAI SDK raise and a dropped `message_start` makes
80	/// anthropic-python raise; both follow a dropped record, so the client running nothing is the
81	/// intended fail-closed outcome.
82	#[test]
83	fn every_fixture_holds_i1_for_every_client() {
84	    for (format, rel) in SETS {
85	        for (name, bytes) in files(rel) {
86	            for (decider, decide) in DECIDERS {
87	                for on_failure in [OnFailure::Block, OnFailure::Allow] {
88	                    let o = drive(format, limits(on_failure), &[&bytes], decide);
89	                    assert!(o.finished, "{rel}/{name} ({decider}, {on_failure:?}) never ended:\n{}", s(&o.out));
90	                    if on_failure == OnFailure::Block {
91	                        check_i1(format, &bytes, &o.out, &o.decided, o.core_failed()).unwrap_or_else(|e| panic!("{rel}/{name} ({decider}): {e}"));
92	                    }
93	                }
94	            }
95	        }
96	    }
97	}
98	
99	/// § 8.3: every single split point gives the same output as one push, for fixtures up to 4 KiB.
100	#[test]
101	fn every_split_point_gives_the_same_output() {
102	    for (format, rel) in SETS {
103	        for (name, bytes) in files(rel) {
104	            if bytes.len() > 4096 {
105	                continue;
106	            }
107	            let whole = drive(format, limits(OnFailure::Block), &[&bytes], &block_named).out;
108	            for i in 0..=bytes.len() {
109	                let split = drive(format, limits(OnFailure::Block), &[&bytes[..i], &bytes[i..]], &block_named).out;
110	                assert_eq!(s(&split), s(&whole), "{rel}/{name} split at {i}");
111	            }
112	        }
113	    }
114	}
115	
116	/// One AC 5 row: what the output must and must not hold under each `on_failure`, and whether
117	/// the shape is a stream-level failure (a malformed record mid-hold or a canonical-form deviation,
118	/// § 6 row 1) rather than a record dropped while nothing is held.
119	struct Row {
120	    name: &'static str,
121	    block_has: &'static [&'static str],
122	    block_lacks: &'static [&'static str],
123	    allow_has: &'static [&'static str],
124	    allow_lacks: &'static [&'static str],
125	    stream_failure: bool,
126	}
127	
128	const fn row(
129	    name: &'static str,
130	    block_has: &'static [&'static str],
131	    block_lacks: &'static [&'static str],
132	    allow_has: &'static [&'static str],
133	    allow_lacks: &'static [&'static str],
134	    stream_failure: bool,
135	) -> Row {
136	    Row {
137	        name,
138	        block_has,
139	        block_lacks,
140	        allow_has,
141	        allow_lacks,
142	        stream_failure,
143	    }
144	}
145	
146	const PASS_THROUGH: &str = ": paigasus-interception pass-through";
147	
148	/// AC 5: each malformed shape shows the § 6 behaviour under both on_failure values.
149	///
150	/// Under `block`, a stream-level failure blocks every open and later hold (`(malformed)` notice
151	/// where a hold was open) and drops later tool-bearing frames, and the stream still ends with its
152	/// end marker. Under `allow` it switches to pass-through. A JSON body on a stream holds no SSE
153	/// record, so nothing is classified and nothing is forwarded in either mode.
154	#[test]
155	fn malformed_shapes_follow_section_6() {
156	    let openai: &[Row] = &[
157	        row("nan_record", &["\"b\""], &[], &["\"b\""], &[], false),
158	        row("duplicate_key_mid_hold", &["(malformed)"], &[], &[PASS_THROUGH], &[], true),
159	        row("case_folded_key", &["\"ok\""], &[], &["\"ok\""], &[], false),
160	        row("proto_key", &["\"ok\""], &[], &["\"ok\""], &[], false),
161	        row("float_index", &["\"ok\""], &[], &["\"ok\""], &[], false),
162	        row("repeated_name", &["(malformed)"], &[], &[PASS_THROUGH], &[], true),
163	        row("oversized", &["(malformed)"], &[], &[PASS_THROUGH], &[], true),
164	        row("after_done", &["data: [DONE]"], &[], &["data: [DONE]"], &[], false),
165	        row("error_mid_hold", &["\"terminal\""], &[], &["\"terminal\""], &[], false),
166	        row("json_body", &[], &["data:", "blocked_json"], &[], &["data:", "blocked_json"], false),
167	        row("lax_line", &["\"ok\""], &[], &["\"ok\""], &[], false),
168	    ];
169	    let anthropic: &[Row] = &[
170	        row(
171	            "event_mismatch",
172	            &["event: message_start", "event: message_stop"],
173	            &["content_block", "blocked_hidden"],
174	            &[PASS_THROUGH],
175	            &[],
176	            true,
177	        ),
178	        row(
179	            "prefilled_input",
180	            &["event: message_start", "event: message_stop"],
181	            &["content_block", "blocked_hidden"],
182	            &[PASS_THROUGH],
183	            &[],
184	            true,
185	        ),
186	        row("index_reuse", &["(malformed)"], &[], &[PASS_THROUGH], &[], true),
187	        // The deviating `message_start` itself is dropped; the stream still ends.
188	        row("prefilled_message", &["event: message_stop"], &["message_start", "blocked_hidden"], &[PASS_THROUGH], &[], true),
189	    ];
190	    for (format, rel, table) in [(Format::OpenAiChat, "openai/malformed", openai), (Format::AnthropicMessages, "anthropic/malformed", anthropic)] {
191	        let all = files(rel);
192	        assert_eq!(all.len(), table.len(), "every {rel} fixture has a row");
193	        for r in table {
194	            let name = r.name;
195	            let bytes = &all.iter().find(|(n, _)| n == name).unwrap_or_else(|| panic!("no fixture {name}")).1;
196	            let blocked = drive(format, limits(OnFailure::Block), &[bytes], &block_named);
197	            let b = s(&blocked.out);
198	            for want in r.block_has {
199	                assert!(b.contains(want), "{rel}/{name} (block) lacks {want:?}:\n{b}");
200	            }
201	            for bad in r.block_lacks {
202	                assert!(!b.contains(bad), "{rel}/{name} (block) holds {bad:?}:\n{b}");
203	            }
204	            let failed = blocked.metrics.contains(&Metric::OnFailure("malformed"));
205	            assert_eq!(failed, r.stream_failure, "{rel}/{name}: stream-level failure");
206	            let a = s(&drive(format, limits(OnFailure::Allow), &[bytes], &block_named).out);
207	            for want in r.allow_has {
208	                assert!(a.contains(want), "{rel}/{name} (allow) lacks {want:?}:\n{a}");
209	            }
210	            for bad in r.allow_lacks {
211	                assert!(!a.contains(bad), "{rel}/{name} (allow) holds {bad:?}:\n{a}");
212	            }
213	        }
214	    }
215	}
