1	// SPDX-License-Identifier: Apache-2.0
2	//! Drives an `Interceptor` synchronously, answering each `Decide` at once.
3	
4	use std::time::Instant;
5	
6	use bytes::Bytes;
7	use paigasus_gateway_core::{Action, BlockCode, Decision, Format, Interceptor, Limits, Metric, OnFailure, ToolCall};
8	
9	pub const TERMINAL: &[u8] = b"\n\ndata: {\"error\":{\"message\":\"terminal\"}}\n\n";
10	
11	pub struct Outcome {
12	    pub out: Vec<u8>,
13	    pub decided: Vec<(ToolCall, Decision)>,
14	    pub max_queued: usize,
15	    /// Whether the interceptor ended once the input was finished and every decision was in.
16	    pub finished: bool,
17	    pub metrics: Vec<Metric>,
18	}
19	
20	impl Outcome {
21	    /// Whether the interceptor dropped a record or took an `on_failure` path. Its output may then
22	    /// be a stream that some client rejects, which is a fail-closed outcome for that client.
23	    pub fn core_failed(&self) -> bool {
24	        self.metrics.iter().any(|m| matches!(m, Metric::RecordDropped(_) | Metric::OnFailure(_)))
25	    }
26	}
27	
28	pub fn limits(on_failure: OnFailure) -> Limits {
29	    Limits {
30	        max_record_bytes: 4096,
31	        max_held_bytes: 16 * 1024,
32	        on_failure,
33	        ..Limits::defaults()
34	    }
35	}
36	
37	/// The block-by-name decider: every call named `blocked_*` is refused.
38	pub fn block_named(c: &ToolCall) -> Decision {
39	    if c.name.starts_with("blocked_") {
40	        Decision::Block { code: BlockCode::Policy }
41	    } else {
42	        Decision::Allow
43	    }
44	}
45	
46	pub fn allow_all(_: &ToolCall) -> Decision {
47	    Decision::Allow
48	}
49	
50	pub fn block_all(_: &ToolCall) -> Decision {
51	    Decision::Block { code: BlockCode::Policy }
52	}
53	
54	pub type Decider = fn(&ToolCall) -> Decision;
55	
56	/// The three deciders spec § 8.1 runs every generated stream under.
57	pub const DECIDERS: &[(&str, Decider)] = &[("block-by-name", block_named), ("block-all", block_all), ("allow-all", allow_all)];
58	
59	pub fn drive(format: Format, limits: Limits, chunks: &[&[u8]], decide: &dyn Fn(&ToolCall) -> Decision) -> Outcome {
60	    let now = Instant::now();
61	    let mut i = Interceptor::new(format, limits, Bytes::from_static(TERMINAL), now);
62	    let mut o = Outcome {
63	        out: Vec::new(),
64	        decided: Vec::new(),
65	        max_queued: 0,
66	        finished: false,
67	        metrics: Vec::new(),
68	    };
69	    let mut pending = Vec::new();
70	    for c in chunks {
71	        pending.extend(i.push(c, now));
72	        run(&mut i, &mut pending, &mut o, decide, now);
73	    }
74	    pending.extend(i.finish(now));
75	    run(&mut i, &mut pending, &mut o, decide, now);
76	    o.finished = i.is_finished();
77	    o
78	}
79	
80	fn run(i: &mut Interceptor, pending: &mut Vec<Action>, o: &mut Outcome, decide: &dyn Fn(&ToolCall) -> Decision, now: Instant) {
81	    while !pending.is_empty() {
82	        o.max_queued = o.max_queued.max(i.queued_bytes());
83	        for a in std::mem::take(pending) {
84	            match a {
85	                Action::Emit(b) => o.out.extend_from_slice(&b),
86	                Action::Decide { hold, calls } => {
87	                    let ds: Vec<Decision> = calls.iter().map(decide).collect();
88	                    o.decided.extend(calls.iter().cloned().zip(ds.iter().copied()));
89	                    pending.extend(i.decided(hold, Ok(ds), now));
90	                }
91	                Action::Count(m) => o.metrics.push(m),
92	                _ => {}
93	            }
94	        }
95	    }
96	    o.max_queued = o.max_queued.max(i.queued_bytes());
97	}
98	
99	/// Split `bytes` at the given cut points, which are taken modulo the length and sorted.
100	pub fn cut<'a>(bytes: &'a [u8], cuts: &[usize]) -> Vec<&'a [u8]> {
101	    if bytes.is_empty() {
102	        return vec![bytes];
103	    }
104	    let mut at: Vec<usize> = cuts.iter().map(|c| c % bytes.len()).collect();
105	    at.sort_unstable();
106	    at.dedup();
107	    let mut out = Vec::new();
108	    let mut prev = 0;
109	    for a in at {
110	        out.push(&bytes[prev..a]);
111	        prev = a;
112	    }
113	    out.push(&bytes[prev..]);
114	    out
115	}
116

1	// SPDX-License-Identifier: Apache-2.0
2	//! P1 (invariant I1) and P2 (bounded memory) over generated hostile streams (spec § 8.1, AC 3, AC 4).
3	
4	mod support;
5	
6	use paigasus_gateway_core::{Format, OnFailure};
7	use proptest::prelude::*;
8	use support::driver::{DECIDERS, Outcome, allow_all, block_named, cut, drive, limits};
9	use support::oracle::{check_i1, runners};
10	use support::streams::{AQuirk, Quirk, anthropic_scenario, openai_scenario, render_anthropic, render_openai};
11	
12	fn show(b: &[u8]) -> String {
13	    String::from_utf8_lossy(b).into_owned()
14	}
15	
16	/// P1 (invariant I1), through every client model; see `oracle::check_i1`.
17	fn check_p1(format: Format, input: &[u8], o: &Outcome) -> Result<(), TestCaseError> {
18	    check_i1(format, input, &o.out, &o.decided, o.core_failed()).map_err(TestCaseError::fail)
19	}
20	
21	fn check_canary(out: &[u8]) -> Result<(), TestCaseError> {
22	    prop_assert!(!show(out).contains("CANARY"), "a blocked call's canary leaked:\n{}", show(out));
23	    Ok(())
24	}
25	
26	/// Every decider of spec § 8.1, `on_failure = block`: no canary under a blocking decider, P1, P2.
27	fn check_all_deciders(format: Format, bytes: &[u8], cuts: &[usize]) -> Result<(), TestCaseError> {
28	    let l = limits(OnFailure::Block);
29	    for (name, decide) in DECIDERS {
30	        let o = drive(format, l, &cut(bytes, cuts), decide);
31	        prop_assert!(o.finished, "decider {name}: the interceptor never ended:\n{}", show(&o.out));
32	        if *name != "allow-all" {
33	            check_canary(&o.out).map_err(|e| TestCaseError::fail(format!("decider {name}: {e}")))?;
34	        }
35	        check_p1(format, bytes, &o).map_err(|e| TestCaseError::fail(format!("decider {name}: {e}")))?;
36	        prop_assert!(o.max_queued <= l.max_held_bytes + l.max_record_bytes, "decider {name}: queue {} over the bound", o.max_queued);
37	    }
38	    Ok(())
39	}
40	
41	proptest! {
42	    #![proptest_config(ProptestConfig::with_cases(10_000))]
43	
44	    #[test]
45	    fn openai_p1_and_p2_hold(s in openai_scenario()) {
46	        check_all_deciders(Format::OpenAiChat, &render_openai(&s), &s.cuts)?;
47	    }
48	
49	    #[test]
50	    fn anthropic_p1_and_p2_hold(s in anthropic_scenario()) {
51	        check_all_deciders(Format::AnthropicMessages, &render_anthropic(&s), &s.cuts)?;
52	    }
53	}
54	
55	proptest! {
56	    #![proptest_config(ProptestConfig::with_cases(2_000))]
57	
58	    /// Observe mode is not a security mode, but it must never panic and must stay bounded. Its
59	    /// output must parse for every client when the scenario has at most one quirk: pass-through
60	    /// forwards later records unclassified (§ 5.3, P-4), so a second quirk reaches the client as
61	    /// the upstream sent it (ruling D9 (a)).
62	    #[test]
63	    fn observe_mode_is_bounded_and_parseable(s in openai_scenario(), a in anthropic_scenario()) {
64	        for (format, bytes, cuts, quirks) in [
65	            (Format::OpenAiChat, render_openai(&s), &s.cuts, s.quirks.len()),
66	            (Format::AnthropicMessages, render_anthropic(&a), &a.cuts, a.quirks.len()),
67	        ] {
68	            let l = limits(OnFailure::Allow);
69	            let o = drive(format, l, &cut(&bytes, cuts), &block_named);
70	            prop_assert!(o.finished, "observe mode never ended:\n{}", show(&o.out));
71	            prop_assert!(o.max_queued <= l.max_held_bytes + l.max_record_bytes);
72	            if quirks <= 1 {
73	                for (model, run) in runners(format) {
74	                    let r = run(&o.out);
75	                    prop_assert!(r.error.is_none() || o.core_failed() || run(&bytes).error.is_some(), "{model} failed in observe mode: {:?}\n{}", r.error, show(&o.out));
76	                }
77	            }
78	        }
79	    }
80	
81	    /// Allow-all with only framing quirks: the decider sees exactly the calls every model derives.
82	    #[test]
83	    fn allow_all_models_agree_with_the_decider(mut s in openai_scenario()) {
84	        s.quirks.retain(|(q, _)| matches!(q, Quirk::Interleave | Quirk::Comments | Quirk::UnknownFields | Quirk::Bom | Quirk::CapitalisedArgKeys));
85	        let bytes = render_openai(&s);
86	        let o = drive(Format::OpenAiChat, limits(OnFailure::Block), &cut(&bytes, &s.cuts), &allow_all);
87	        prop_assert!(o.finished);
88	        check_p1(Format::OpenAiChat, &bytes, &o)?;
89	        if !o.core_failed() {
90	            for (model, run) in runners(Format::OpenAiChat) {
91	                let derived = run(&o.out);
92	                if derived.error.is_some() {
93	                    // LangChain raises on any custom tool call, upstream bytes included.
94	                    prop_assert!(run(&bytes).error.is_some(), "{} raised: {:?}", model, derived.error);
95	                    continue;
96	                }
97	                prop_assert_eq!(derived.calls.len(), o.decided.len(), "{}: every decided call reaches the client", model);
98	            }
99	        }
100	    }
101	}
102	
103	proptest! {
104	    #![proptest_config(ProptestConfig::with_cases(1_000))]
105	
106	    /// Argument keys are application data (I-1): PascalCase, `constructor` and `prototype` keys
107	    /// in arguments never make the core fail, and every model derives exactly the decided calls.
108	    #[test]
109	    fn capitalised_argument_keys_are_conforming(mut s in openai_scenario(), mut a in anthropic_scenario()) {
110	        s.quirks = vec![(Quirk::CapitalisedArgKeys, 0)];
111	        for c in s.choices.iter_mut().skip(1) {
112	            c.calls.clear(); // later choices' tool calls are unsupported while interception is on
113	        }
114	        a.quirks = vec![(AQuirk::CapitalisedArgKeys, 0)];
115	        for (format, bytes, cuts) in [(Format::OpenAiChat, render_openai(&s), &s.cuts), (Format::AnthropicMessages, render_anthropic(&a), &a.cuts)] {
116	            let o = drive(format, limits(OnFailure::Block), &cut(&bytes, cuts), &allow_all);
117	            prop_assert!(o.finished);
118	            prop_assert!(!o.core_failed(), "the core failed on capitalised argument keys:\n{}", show(&bytes));
119	            check_p1(format, &bytes, &o)?;
120	            for (model, run) in runners(format) {
121	                let derived = run(&o.out);
122	                if derived.error.is_some() {
123	                    // LangChain raises on any custom tool call, upstream bytes included.
124	                    prop_assert!(run(&bytes).error.is_some(), "{} raised: {:?}", model, derived.error);
125	                    continue;
126	                }
127	                prop_assert_eq!(derived.calls.len(), o.decided.len(), "{}: every decided call reaches the client", model);
128	            }
129	        }
130	    }
131	}
