1	// SPDX-License-Identifier: Apache-2.0
2	//! Canonical tool-call assembly for one OpenAI choice (spec § 4.3, D9).
3	//!
4	//! Only choice 0 may carry tool calls, and only at array position 0 of its chunk, because LangChain
5	//! reads `choices[0]` of every chunk and ignores `choice.index`. A `type` that does not match the body's shape is a deviation, because
6	//! clients ignore `type` and run the body. Kind Other is only for a call with no body at all.
7	//!
8	//! The client SDKs disagree on everything outside this form. openai-python concatenates every
9	//! string except `index` and `type`, so a second `name` fragment turns `safe_` into `safe_rm`.
10	//! openai-node replaces the name, and LangChain merges by index value. Inside the canonical form
11	//! they all agree, so the decider sees exactly what every client will run.
12	//!
13	//! Every check runs on a small copy of the state ([`Check`]) before anything is changed, so a
14	//! deviation leaves the assembly exactly as it was.
15	//!
16	//! A function call's arguments are what clients parse, so at completion they must be one complete
17	//! JSON value ([`complete_arguments`]), as an Anthropic `tool_use` input must. LangChain
18	//! partial-parses a truncated string (`{"cmd":"ls` runs as `{"cmd":"ls"}`) and openai-node can
19	//! partial-parse it too, so the decider would see a string the client reads differently.
20	
21	use serde_json::Value;
22	
23	use crate::json::{check_numbers, parse_value_strict};
24	use crate::openai::classify::{Fragment, NameArgs};
25	use crate::protocol::{Deviation, MAX_IDENTIFIER_BYTES, raw_len};
26	use crate::types::{ToolCall, ToolCallKind};
27	
28	#[derive(Clone, Copy, PartialEq, Eq)]
29	enum Shape {
30	    Function,
31	    Custom,
32	}
33	
34	/// The class of a `type` value: all that the canonical checks read of it.
35	#[derive(Clone, Copy, PartialEq, Eq)]
36	enum TyClass {
37	    Function,
38	    Custom,
39	    Other,
40	}
41	
42	/// What the canonical checks read of one call. It is small, so a whole record can be checked
43	/// against a copy before anything is changed: a deviation must never leave half-applied state, for
44	/// example a hold marked open that the interceptor never registered.
45	#[derive(Clone, Copy, Default)]
46	struct Shadow {
47	    id: bool,
48	    ty: Option<TyClass>,
49	    shape: Option<Shape>,
50	    name: bool,
51	}
52	
53	/// The canonical-form state of one choice (spec § 4.3), without the strings.
54	#[derive(Clone, Default)]
55	pub(crate) struct Check {
56	    calls: Vec<Shadow>,
57	    /// `Some(has_name)` once a legacy `function_call` fragment arrived.
58	    legacy: Option<bool>,
59	}
60	
61	fn once(slot: &mut bool, present: bool, why: &'static str) -> Result<(), Deviation> {
62	    if present {
63	        if *slot {
64	            return Err(Deviation(why));
65	        }
66	        *slot = true;
67	    }
68	    Ok(())
69	}
70	
71	/// A tool-call id or name over `MAX_IDENTIFIER_BYTES` is a deviation (each arrives at most once).
72	fn long_check(id: Option<&str>, name: Option<&str>) -> Result<(), Deviation> {
73	    if id.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) || name.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) {
74	        return Err(Deviation("long_identifier"));
75	    }
76	    Ok(())
77	}
78	
79	impl Check {
80	    fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
81	        let mixes = (legacy.is_some() && (!frags.is_empty() || !self.calls.is_empty())) || (!frags.is_empty() && self.legacy.is_some());
82	        if mixes {
83	            return Err(Deviation("legacy_and_tool_calls"));
84	        }
85	        if let Some(l) = legacy {
86	            long_check(None, l.name.as_deref())?;
87	            once(self.legacy.get_or_insert(false), l.name.is_some(), "repeated_name")?;
88	        }
89	        for f in frags {
90	            let pos = f.index as usize;
91	            if pos == self.calls.len() {
92	                self.calls.push(Shadow::default());
93	            } else if pos > self.calls.len() {
94	                return Err(Deviation("index_gap"));
95	            }
96	            let b = &mut self.calls[pos];
97	            long_check(f.id.as_deref(), f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.name.as_deref()))?;
98	            once(&mut b.id, f.id.is_some(), "repeated_id")?;
99	            if let Some(t) = &f.ty {
100	                // The type names a bodyless Other call, so it is bounded like an id or a name.
101	                long_check(Some(t), None)?;
102	                if b.ty.is_some() {
103	                    return Err(Deviation("repeated_type"));
104	                }
105	                b.ty = Some(match t.as_str() {
106	                    "function" => TyClass::Function,
107	                    "custom" => TyClass::Custom,
108	                    _ => TyClass::Other,
109	                });
110	            }
111	            let (shape, na) = match (&f.function, &f.custom) {
112	                (Some(na), None) => (Some(Shape::Function), Some(na)),
113	                (None, Some(na)) => (Some(Shape::Custom), Some(na)),
114	                _ => (None, None),
115	            };
116	            if let Some(s) = shape {
117	                match b.shape {
118	                    None => b.shape = Some(s),
119	                    Some(prev) if prev != s => return Err(Deviation("shape_changed")),
120	                    Some(_) => {}
121	                }
122	            }
123	            if let Some(na) = na {
124	                once(&mut b.name, na.name.is_some(), "repeated_name")?;
125	            }
126	        }
127	        Ok(())
128	    }
129	
130	    /// The kind of every call once the choice finishes, or the deviation that finishing is.
131	    pub(crate) fn finish(&self) -> Result<Vec<ToolCallKind>, Deviation> {
132	        if let Some(has_name) = self.legacy {
133	            if !has_name {
134	                return Err(Deviation("missing_name"));
135	            }
136	            return Ok(vec![ToolCallKind::LegacyFunctionCall]);
137	        }
138	        self.calls
139	            .iter()
140	            .map(|b| {
141	                // Clients ignore `type` and run the body, so any type other than the one the
142	                // body's shape expects is a deviation, never kind Other (spec I1).
143	                let kind = match (b.shape, b.ty) {
144	                    (Some(Shape::Function), Some(TyClass::Function) | None) => ToolCallKind::Function,
145	                    (Some(Shape::Custom), Some(TyClass::Custom) | None) => ToolCallKind::Custom,
146	                    (Some(_), Some(_)) => return Err(Deviation("type_shape_mismatch")),
147	                    (None, Some(TyClass::Function | TyClass::Custom)) => return Err(Deviation("missing_body")),
148	                    (None, _) => ToolCallKind::Other,
149	                };
150	                if kind != ToolCallKind::Other && !b.name {
151	                    return Err(Deviation("missing_name"));
152	                }
153	                Ok(kind)
154	            })
155	            .collect()
156	    }
157	}
