159	#[derive(Default)]
160	struct CallBuild {
161	    id: Option<String>,
162	    ty: Option<String>,
163	    name: Option<String>,
164	    args: String,
165	    raws: Vec<Value>,
166	}
167	
168	#[derive(Default)]
169	pub(crate) struct ChoiceAssembly {
170	    calls: Vec<CallBuild>,
171	    legacy: Option<CallBuild>,
172	    check: Check,
173	    /// The bytes held in arguments and raw entries.
174	    retained: usize,
175	    /// An observed choice outgrew the cap: it keeps nothing and is never decided (§ 5.3, D13).
176	    overflowed: bool,
177	}
178	
179	/// Kind Other carries its raw entries. serde_json rounds an integer beyond u64/i64, so the decider
180	/// would read a different number than a client that keeps the exact one (I1, as for bodies).
181	fn check_raws<'a>(raws: impl IntoIterator<Item = &'a Value>) -> Result<(), Deviation> {
182	    raws.into_iter().try_for_each(check_numbers).map_err(|_| Deviation("lossy_number"))
183	}
184	
185	/// Tool data is allowed only in choice 0, and only at array position 0 of its chunk (spec § 4.3).
186	/// LangChain reads `choices[0]` of every chunk and ignores `choice.index`. So a call split across
187	/// choices 0 and 1 would be merged by it but assembled separately here (`multi_choice_tool_calls`),
188	/// and a choice-0 fragment behind another choice's entry would never reach it
189	/// (`choice_position`). Text in other choices and positions stays allowed.
190	pub(crate) fn check_tool_choice(choice: u32, position: usize, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
191	    if frags.is_empty() && legacy.is_none() {
192	        return Ok(());
193	    }
194	    if choice != 0 {
195	        return Err(Deviation("multi_choice_tool_calls"));
196	    }
197	    if position != 0 {
198	        return Err(Deviation("choice_position"));
199	    }
200	    Ok(())
201	}
202	
203	/// The arguments the decider sees for a completed call of `kind`. A function or legacy call's
204	/// arguments must be one complete JSON value; an empty string is presented as `{}`, as an empty
205	/// Anthropic input is. A custom tool's input is free-form text and is not checked; kind Other
206	/// carries its raw entry.
207	pub(crate) fn complete_arguments(kind: ToolCallKind, args: String) -> Result<String, Deviation> {
208	    match kind {
209	        ToolCallKind::Function | ToolCallKind::LegacyFunctionCall => {
210	            if args.is_empty() {
211	                Ok("{}".to_owned())
212	            } else if parse_value_strict(args.as_bytes()).is_ok() {
213	                Ok(args)
214	            } else {
215	                Err(Deviation("incomplete_arguments"))
216	            }
217	        }
218	        _ => Ok(args),
219	    }
220	}
221	
222	impl ChoiceAssembly {
223	    /// The canonical-form state after these fragments, or the deviation they are. Changes nothing.
224	    pub(crate) fn check(&self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<Check, Deviation> {
225	        let mut c = self.check.clone();
226	        c.apply(frags, legacy)?;
227	        Ok(c)
228	    }
229	
230	    /// The current canonical-form state.
231	    pub(crate) fn state(&self) -> &Check {
232	        &self.check
233	    }
234	
235	    /// Apply fragments that [`ChoiceAssembly::check`] accepted, with `after` its result. Cannot fail.
236	    pub(crate) fn commit(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, after: Check) {
237	        if let Some(l) = legacy {
238	            let b = self.legacy.get_or_insert_with(CallBuild::default);
239	            if let Some(n) = &l.name {
240	                b.name = Some(n.clone());
241	            }
242	            if let Some(a) = &l.args {
243	                b.args.push_str(a);
244	                self.retained += a.len();
245	            }
246	        }
247	        for f in frags {
248	            let pos = f.index as usize;
249	            while self.calls.len() <= pos {
250	                self.calls.push(CallBuild::default());
251	            }
252	            let b = &mut self.calls[pos];
253	            if let Some(id) = &f.id {
254	                b.id = Some(id.clone());
255	            }
256	            if let Some(t) = &f.ty {
257	                b.ty = Some(t.clone());
258	            }
259	            if let Some(na) = f.function.as_ref().or(f.custom.as_ref()) {
260	                if let Some(n) = &na.name {
261	                    b.name = Some(n.clone());
262	                }
263	                if let Some(a) = &na.args {
264	                    b.args.push_str(a);
265	                    self.retained += a.len();
266	                }
267	            }
268	            // Only kind Other reads its raw entries, and only a call with no body is Other. A call
269	            // whose body arrived drops them, so its arguments are not held twice.
270	            if after.calls.get(pos).is_some_and(|s| s.shape.is_none()) {
271	                self.retained += raw_len(&f.raw);
272	                b.raws.push(f.raw.clone());
273	            } else if !b.raws.is_empty() {
274	                self.retained -= std::mem::take(&mut b.raws).iter().map(raw_len).sum::<usize>();
275	            }
276	        }
277	        self.check = after;
278	    }
279	
280	    /// Observe mode (§ 5.3): apply what fits, and stop retaining once the choice holds more than
281	    /// `cap` bytes. The choice is then never decided, as a pass-through call is not.
282	    pub(crate) fn observe(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, cap: usize) {
283	        if self.overflowed {
284	            return;
285	        }
286	        let _ = self.apply(frags, legacy);
287	        if self.retained > cap {
288	            self.overflowed = true;
289	            self.drop_buffers();
290	        }
291	    }
292	
293	    pub(crate) fn overflowed(&self) -> bool {
294	        self.overflowed
295	    }
296	
297	    /// Drop every argument and raw buffer, keeping the names. Used once the choice finished.
298	    pub(crate) fn drop_buffers(&mut self) {
299	        for b in self.calls.iter_mut().chain(&mut self.legacy) {
300	            b.args = String::new();
301	            b.raws = Vec::new();
302	        }
303	        self.retained = 0;
304	    }
305	
306	    /// Check, then commit. On a deviation nothing is changed.
307	    pub(crate) fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
308	        let after = self.check(frags, legacy)?;
309	        self.commit(frags, legacy, after);
310	        Ok(())
311	    }
312	
313	    /// Phase-1 form of [`ChoiceAssembly::finish`]: whether finishing would succeed once `frags` and
314	    /// `legacy` (already accepted by [`ChoiceAssembly::check`], with result `after`) are applied.
315	    /// Changes nothing.
316	    pub(crate) fn check_finish(&self, frags: &[Fragment], legacy: Option<&NameArgs>, after: &Check) -> Result<(), Deviation> {
317	        let kinds = after.finish()?;
318	        let pending = |own: Option<&CallBuild>, more: &mut dyn Iterator<Item = &str>| -> String {
319	            let mut a = own.map(|b| b.args.clone()).unwrap_or_default();
320	            more.for_each(|x| a.push_str(x));
321	            a
322	        };
323	        if after.legacy.is_some() {
324	            let args = pending(self.legacy.as_ref(), &mut legacy.and_then(|l| l.args.as_deref()).into_iter());
325	            return complete_arguments(ToolCallKind::LegacyFunctionCall, args).map(drop);
326	        }
327	        for (i, kind) in kinds.into_iter().enumerate() {
328	            let mine = frags.iter().filter(|f| f.index as usize == i);
329	            if kind == ToolCallKind::Other {
330	                check_raws(self.calls.get(i).into_iter().flat_map(|b| &b.raws).chain(mine.map(|f| &f.raw)))?;
331	                continue;
332	            }
333	            let mut more = mine.filter_map(|f| f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.args.as_deref()));
334	            complete_arguments(kind, pending(self.calls.get(i), &mut more))?;
335	        }
336	        Ok(())
337	    }
338	
339	    /// The completed calls. Moves the buffers out, so a finished choice keeps no arguments.
340	    pub(crate) fn finish(&mut self, choice: u32) -> Result<Vec<ToolCall>, Deviation> {
341	        let kinds = self.check.finish()?;
342	        self.retained = 0;
343	        if let Some(b) = &mut self.legacy {
344	            return Ok(vec![ToolCall {
345	                choice,
346	                position: 0,
347	                id: None,
348	                name: b.name.clone().unwrap_or_default(),
349	                kind: ToolCallKind::LegacyFunctionCall,
350	                arguments: complete_arguments(ToolCallKind::LegacyFunctionCall, std::mem::take(&mut b.args))?,
351	            }]);
352	        }
353	        let mut out = Vec::with_capacity(self.calls.len());
354	        for ((i, b), kind) in self.calls.iter_mut().enumerate().zip(kinds) {
355	            let (name, arguments) = if kind == ToolCallKind::Other {
356	                let name = b.name.clone().or_else(|| b.ty.clone()).unwrap_or_else(|| "unknown".to_owned());
357	                let raws = std::mem::take(&mut b.raws);
358	                check_raws(&raws)?;
359	                (name, serde_json::to_string(&raws).expect("a Value array always serializes"))
360	            } else {
361	                b.raws = Vec::new();
362	                (b.name.clone().unwrap_or_default(), complete_arguments(kind, std::mem::take(&mut b.args))?)
363	            };
364	            let position = u32::try_from(i).expect("at most 128 calls per choice");
365	            out.push(ToolCall {
366	                choice,
367	                position,
368	                id: b.id.clone(),
369	                name,
370	                kind,
371	                arguments,
372	            });
373	        }
374	        Ok(out)
375	    }
376	
377	    /// The argument and raw-entry bytes held, measured exactly. Tests only.
378	    #[cfg(test)]
379	    pub(crate) fn retained(&self) -> usize {
380	        self.calls.iter().chain(&self.legacy).map(|b| b.args.len() + crate::protocol::raws_len(&b.raws)).sum()
381	    }
382	
383	    pub(crate) fn names(&self) -> Vec<(u32, String)> {
384	        let name = |b: &CallBuild| b.name.clone().unwrap_or_else(|| "unknown".to_owned());
385	        if let Some(b) = &self.legacy {
386	            return vec![(0, name(b))];
387	        }
388	        self.calls.iter().enumerate().map(|(i, b)| (u32::try_from(i).expect("at most 128 calls per choice"), name(b))).collect()
389	    }
390	}
