1	// SPDX-License-Identifier: Apache-2.0
2	//! OpenAI stream-chunk classification by a positive allowlist (spec § 4.2, D6).
3	//!
4	//! A chunk is tool-free only when it matches the strict tool-free shape. A non-empty
5	//! `tool_calls` or a `function_call` object makes it tool-bearing. Anything else is malformed.
6	//! "Has a `tool_calls` key" would be wrong both ways: it misses `tool_calls` as an object, and it
7	//! holds every text delta of an upstream that sends `"tool_calls": []`.
8	//!
9	//! A chunk that carries tool data or a `finish_reason` must say `"object":"chat.completion.chunk"`
10	//! (a body: `"chat.completion"`). openai-python's `ChatCompletionStream` skips every chunk whose
11	//! `object` differs (it filters Azure's async content-filter chunks), so a fragment in such a chunk
12	//! would reach the decider but not that client. Text-only chunks are not checked: skipping them
13	//! changes no tool call.
14	
15	use serde_json::{Map, Value};
16	
17	use crate::json::{MAX_OPENAI_INDEX, Malformed, index_of, opt_obj, opt_str};
18	
19	pub(crate) enum Chunk {
20	    Choices(Vec<ChoiceView>),
21	    UpstreamError,
22	}
23	
24	pub(crate) struct ChoiceView {
25	    pub index: u32,
26	    pub fragments: Vec<Fragment>,
27	    pub legacy: Option<NameArgs>,
28	    pub finish_reason: Option<String>,
29	    pub has_text: bool,
30	}
31	
32	pub(crate) struct Fragment {
33	    pub index: u32,
34	    pub id: Option<String>,
35	    pub ty: Option<String>,
36	    pub function: Option<NameArgs>,
37	    pub custom: Option<NameArgs>,
38	    /// The whole entry, for kind Other (§ 4.1).
39	    pub raw: Value,
40	}
41	
42	pub(crate) struct NameArgs {
43	    pub name: Option<String>,
44	    pub args: Option<String>,
45	}
46	
47	/// The `object` a chunk needs once it carries tool data or a `finish_reason`, and a body once it
48	/// carries tool calls (spec § 11): openai-python skips a chunk with any other `object`.
49	pub(crate) const CHUNK_OBJECT: &str = "chat.completion.chunk";
50	pub(crate) const BODY_OBJECT: &str = "chat.completion";
51	
52	/// openai-python skips a chunk whose `object` is not `expected`. When `carries` (tool data or a
53	/// `finish_reason`), such a chunk is malformed; otherwise it is not checked.
54	pub(crate) fn check_object(top: &Map<String, Value>, expected: &str, carries: bool) -> Result<(), Malformed> {
55	    if carries && top.get("object").and_then(Value::as_str) != Some(expected) {
56	        return Err(Malformed("object"));
57	    }
58	    Ok(())
59	}
60	
61	pub(crate) fn chunk(v: &Value) -> Result<Chunk, Malformed> {
62	    let Value::Object(top) = v else { return Err(Malformed("not_object")) };
63	    if top.contains_key("error") {
64	        return if top.contains_key("choices") {
65	            Err(Malformed("error_and_choices"))
66	        } else {
67	            Ok(Chunk::UpstreamError)
68	        };
69	    }
70	    let choices = match top.get("choices") {
71	        None => Vec::new(),
72	        Some(Value::Array(a)) => {
73	            let v: Vec<ChoiceView> = a.iter().map(choice).collect::<Result<_, _>>()?;
74	            // LangChain takes choices[0] of every chunk, so a repeated index could be merged by it.
75	            if v.iter().enumerate().any(|(i, x)| v[..i].iter().any(|y| y.index == x.index)) {
76	                return Err(Malformed("duplicate_choice_index"));
77	            }
78	            v
79	        }
80	        Some(_) => return Err(Malformed("choices")),
81	    };
82	    let carries = choices.iter().any(|c| !c.fragments.is_empty() || c.legacy.is_some() || c.finish_reason.is_some());
83	    check_object(top, CHUNK_OBJECT, carries)?;
84	    Ok(Chunk::Choices(choices))
85	}
86	
87	fn choice(v: &Value) -> Result<ChoiceView, Malformed> {
88	    let Value::Object(c) = v else { return Err(Malformed("choice")) };
89	    if c.contains_key("message") {
90	        return Err(Malformed("message_in_chunk"));
91	    }
92	    let index = index_of(c.get("index"), MAX_OPENAI_INDEX)?;
93	    let finish_reason = opt_str(c.get("finish_reason"), "finish_reason")?;
94	    let (fragments, legacy, has_text) = match c.get("delta") {
95	        None => (Vec::new(), None, false),
96	        Some(Value::Object(d)) => delta(d)?,
97	        Some(_) => return Err(Malformed("delta")),
98	    };
99	    Ok(ChoiceView {
100	        index,
101	        fragments,
102	        legacy,
103	        finish_reason,
104	        has_text,
105	    })
106	}
107	
108	fn delta(d: &Map<String, Value>) -> Result<(Vec<Fragment>, Option<NameArgs>, bool), Malformed> {
109	    let fragments = match d.get("tool_calls") {
110	        None | Some(Value::Null) => Vec::new(),
111	        Some(Value::Array(a)) => a.iter().map(fragment).collect::<Result<_, _>>()?,
112	        Some(_) => return Err(Malformed("tool_calls")),
113	    };
114	    let legacy = opt_obj(d.get("function_call"), "function_call")?.map(|f| name_args(f, "arguments")).transpose()?;
115	    let has_text = match d.get("content") {
116	        None | Some(Value::Null) => false,
117	        Some(Value::String(s)) => !s.is_empty(),
118	        Some(_) => return Err(Malformed("content")),
119	    };
120	    Ok((fragments, legacy, has_text))
121	}
122	
123	fn fragment(v: &Value) -> Result<Fragment, Malformed> {
124	    let Value::Object(e) = v else { return Err(Malformed("tool_call")) };
125	    let index = index_of(e.get("index"), MAX_OPENAI_INDEX)?;
126	    fragment_at(v, index)
127	}
128	
129	/// A tool-call entry at a known `index`. A non-stream body has no per-entry `index`, so its
130	/// array position stands in (spec § 4.2).
131	pub(crate) fn fragment_at(v: &Value, index: u32) -> Result<Fragment, Malformed> {
132	    let Value::Object(e) = v else { return Err(Malformed("tool_call")) };
133	    let id = opt_str(e.get("id"), "id")?;
134	    let ty = opt_str(e.get("type"), "type")?;
135	    let function = opt_obj(e.get("function"), "function")?.map(|f| name_args(f, "arguments")).transpose()?;
136	    let custom = opt_obj(e.get("custom"), "custom")?.map(|f| name_args(f, "input")).transpose()?;
137	    if function.is_some() && custom.is_some() {
138	        return Err(Malformed("function_and_custom"));
139	    }
140	    Ok(Fragment {
141	        index,
142	        id,
143	        ty,
144	        function,
145	        custom,
146	        raw: v.clone(),
147	    })
148	}
149	
150	pub(crate) fn name_args(f: &Map<String, Value>, args_key: &'static str) -> Result<NameArgs, Malformed> {
151	    Ok(NameArgs {
152	        name: opt_str(f.get("name"), "name")?,
153	        args: opt_str(f.get(args_key), args_key)?,
154	    })
155	}
