260	            r#"{"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}"#.to_owned(),
261	        ] {
262	            assert_eq!(raw(&bad).err(), Some(Malformed("object")), "{bad}");
263	        }
264	        assert!(raw(&format!(r#"{{"object":"chat.completion.chunk","choices":[{{"index":0,{frag}}}]}}"#)).is_ok());
265	        // Text-only and empty chunks are not checked: skipping them changes no tool call.
266	        for ok in [
267	            r#"{"choices":[{"index":0,"delta":{"content":"hi"},"finish_reason":null}]}"#,
268	            r#"{"choices":[],"usage":{"total_tokens":1}}"#,
269	            r#"{"object":"","choices":[]}"#,
270	        ] {
271	            assert!(raw(ok).is_ok(), "{ok}");
272	        }
273	    }
274	}
