17	/// The upstream fields a notice chunk copies, in upstream order. `object` is not copied: a notice
18	/// chunk always says `chat.completion.chunk`, or openai-python would skip it.
19	const META_KEYS: [&str; 4] = ["id", "created", "model", "system_fingerprint"];
20	
21	#[derive(Default)]
22	struct ChoiceState {
23	    asm: ChoiceAssembly,
24	    hold_open: bool,
25	    finished: bool,
26	    has_text: bool,
27	    notice_done: bool,
28	    /// The (position, name) of the calls handed to the decider, in hold order. Never their
29	    /// arguments: a finished choice keeps none.
30	    calls: Vec<(u32, String)>,
31	}
32	
33	pub(crate) struct OpenAiStream {
34	    choices: BTreeMap<u32, ChoiceState>,
35	    meta: Map<String, Value>,
36	    /// The most an observed choice may retain (D13, § 5.3).
37	    cap: usize,
38	}
39	
40	impl Default for OpenAiStream {
41	    fn default() -> Self {
42	        Self::with_cap(crate::limits::Limits::defaults().max_held_bytes)
43	    }
44	}
45	
46	impl OpenAiStream {
47	    pub(crate) fn with_cap(cap: usize) -> Self {
48	        OpenAiStream {
49	            choices: BTreeMap::new(),
50	            meta: Map::new(),
51	            cap,
52	        }
53	    }
54	}
