56	/// The scalar (string or number) `META_KEYS` fields of a record. A non-scalar value is skipped.
57	fn meta_of(v: &Value) -> Map<String, Value> {
58	    let mut m = Map::new();
59	    if let Value::Object(top) = v {
60	        for k in META_KEYS {
61	            if let Some(x @ (Value::String(_) | Value::Number(_))) = top.get(k) {
62	                m.insert(k.to_owned(), x.clone());
63	            }
64	        }
65	    }
66	    m
67	}
68	
69	fn notice_chunk(meta: &Map<String, Value>, choice: u32, text: &str) -> Bytes {
70	    let mut m = Map::new();
71	    for (k, v) in meta {
72	        m.insert(k.clone(), v.clone());
73	        if k == "id" {
74	            m.insert("object".to_owned(), classify::CHUNK_OBJECT.into());
75	        }
76	    }
77	    m.entry("object").or_insert_with(|| classify::CHUNK_OBJECT.into());
78	    m.insert("choices".to_owned(), json!([{"index": choice, "delta": {"content": text}, "finish_reason": null}]));
79	    sse::frame(None, &serde_json::to_vec(&Value::Object(m)).expect("a Value always serializes"))
80	}
81	
82	impl ChoiceState {
83	    /// The (position, name) of every call the hold knows.
84	    fn known(&self) -> Vec<(u32, String)> {
85	        if self.calls.is_empty() { self.asm.names() } else { self.calls.clone() }
86	    }
87	
88	    fn notice_text(&self, verdict: &Verdict) -> String {
89	        let lines: Vec<String> = self
90	            .known()
91	            .iter()
92	            .enumerate()
93	            .filter_map(|(slot, (_, name))| verdict.block_code(slot).map(|code| notice_line(name, code)))
94	            .collect();
95	        let body = if lines.is_empty() {
96	            notice_line("unknown", verdict.block_code(0).unwrap_or(crate::types::BlockCode::Malformed))
97	        } else {
98	            lines.join("\n")
99	        };
100	        if self.has_text { format!("\n\n{body}") } else { body }
101	    }
102	
103	    fn allowed_left(&self, verdict: &Verdict) -> usize {
104	        (0..self.known().len()).filter(|slot| verdict.block_code(*slot).is_none()).count()
105	    }
106	}
107	
108	impl Protocol for OpenAiStream {
109	    fn step(&mut self, rec: Record, verdicts: &Verdicts) -> Result<Step, StepError> {
110	        if rec.data == b"[DONE]" {
111	            return Ok(Step::End(Frame {
112	                event: None,
113	                payload: rec.data,
114	                value: None,
115	                touches: Vec::new(),
116	            }));
117	        }
118	        let value = parse_strict(&rec.data)?;
119	        let choices = match classify::chunk(&value)? {
120	            Chunk::UpstreamError => {
121	                return Ok(Step::UpstreamError(Frame {
122	                    event: None,
123	                    payload: rec.data,
124	                    value: Some(value),
125	                    touches: Vec::new(),
126	                }));
127	            }
128	            Chunk::Choices(c) => c,
129	        };
130	        // Phase 1 checks the whole record and changes nothing. A deviation in any choice drops the
131	        // record, so no choice may have been changed by then: a hold marked open that the
132	        // interceptor never registered would wait for a verdict for ever.
133	        let empty = ChoiceAssembly::default();
134	        let mut planned: Vec<Option<Check>> = Vec::with_capacity(choices.len());
135	        let mut new_choices = 0;
136	        for (position, cv) in choices.iter().enumerate() {
137	            let key = HoldKey::Choice(cv.index);
138	            let st = self.choices.get(&cv.index);
139	            if st.is_none() {
140	                if cv.index as usize != self.choices.len() + new_choices {
141	                    return Err(StepError::Deviation("choice_order"));
142	                }
143	                new_choices += 1;
144	            }
145	            let (finished, hold_open, asm) = st.map_or((false, false, &empty), |s| (s.finished, s.hold_open, &s.asm));
146	            let tools = !cv.fragments.is_empty() || cv.legacy.is_some();
147	            let undecided = !verdicts.contains_key(&key);
148	            let mut after = None;
149	            if tools {
150	                assembly::check_tool_choice(cv.index, position, &cv.fragments, cv.legacy.as_ref())?;
151	                if finished {
152	                    return Err(StepError::Deviation("late_fragment"));
153	                }
154	                if undecided {
155	                    after = Some(asm.check(&cv.fragments, cv.legacy.as_ref())?);
156	                }
157	            }
158	            if cv.finish_reason.is_some() {
159	                if finished {
160	                    return Err(StepError::Deviation("second_finish"));
161	                }
162	                if (hold_open || tools) && undecided {
163	                    asm.check_finish(&cv.fragments, cv.legacy.as_ref(), after.as_ref().unwrap_or(asm.state()))?;
164	                }
165	            }
166	            planned.push(after);
167	        }
168	        // Phase 2 applies the checked record. Only an accepted record updates the notice meta.
169	        for (k, v) in meta_of(&value) {
170	            self.meta.insert(k, v);
171	        }
172	        let (mut touches, mut opened, mut completed) = (Vec::new(), Vec::new(), Vec::new());
173	        for (cv, after) in choices.into_iter().zip(planned) {
174	            let key = HoldKey::Choice(cv.index);
175	            let st = self.choices.entry(cv.index).or_default();
176	            if cv.has_text {
177	                st.has_text = true;
178	            }
179	            if !cv.fragments.is_empty() || cv.legacy.is_some() {
180	                match (verdicts.get(&key), after) {
181	                    (None, Some(after)) => st.asm.commit(&cv.fragments, cv.legacy.as_ref(), after),
182	                    (Some(Verdict::PassThrough), _) => st.asm.observe(&cv.fragments, cv.legacy.as_ref(), self.cap),
183	                    _ => {}
184	                }
185	                if !st.hold_open {
186	                    st.hold_open = true;
187	                    opened.push(key);
188	                }
189	                touches.push(key);
190	            }
191	            if cv.finish_reason.is_some() {
192	                st.finished = true;
193	                if st.hold_open {
194	                    touches.push(key);
195	                    let finished = match verdicts.get(&key) {
196	                        // Phase 1 ran the same check on the same state, so this cannot fail.
197	                        None => Some(st.asm.finish(cv.index)?),
198	                        Some(Verdict::PassThrough) if !st.asm.overflowed() => st.asm.finish(cv.index).ok(),
199	                        Some(_) => None,
200	                    };
201	                    st.asm.drop_buffers();
202	                    if let Some(calls) = finished {
203	                        st.calls = calls.iter().map(|c| (c.position, c.name.clone())).collect();
204	                        completed.push((key, calls));
205	                    }
206	                }
207	            }
208	        }
209	        touches.sort();
210	        touches.dedup();
211	        Ok(Step::Frame {
212	            frame: Frame {
213	                event: None,
214	                payload: rec.data,
215	                value: Some(value),
216	                touches,
217	            },
218	            opened,
219	            completed,
220	            reports: Vec::new(),
221	        })
222	    }
223	
224	    fn incomplete(&self) -> Vec<HoldKey> {
225	        self.choices.iter().filter(|(_, s)| s.hold_open && !s.finished).map(|(c, _)| HoldKey::Choice(*c)).collect()
226	    }
227	
228	    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes> {
229	        let Some(mut value) = frame.value else {
230	            let mut out = self.closing(verdicts);
231	            out.push(sse::frame(None, &frame.payload));
232	            return out;
233	        };
234	        let blocking: Vec<u32> = frame
235	            .touches
236	            .iter()
237	            .filter_map(|k| match (k, verdicts.get(k)) {
238	                (HoldKey::Choice(c), Some(v)) if v.blocks_any() => Some(*c),
239	                _ => None,
240	            })
241	            .collect();
242	        if blocking.is_empty() {
243	            return vec![sse::frame(None, &frame.payload)];
244	        }
245	        let meta = meta_of(&value);
246	        let mut notices = Vec::new();
247	        if let Some(Value::Array(choices)) = value.get_mut("choices") {
248	            for ch in choices.iter_mut() {
249	                let idx = ch.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
250	                if let Some(v) = verdicts.get(&HoldKey::Choice(idx)).filter(|_| blocking.contains(&idx)) {
251	                    let st = self.choices.entry(idx).or_default();
252	                    if let Some(text) = rewrite_choice(ch, v, st) {
253	                        notices.push(notice_chunk(&meta, idx, &text));
254	                    }
255	                }
256	            }
257	        }
258	        // P-10: never drop the frame or a choice entry. openai-python finds a choice by list
259	        // position, so a missing first appearance would shift every later choice.
260	        notices.push(sse::frame(None, &serde_json::to_vec(&value).expect("a Value always serializes")));
261	        notices
262	    }
263	
264	    fn closing(&mut self, verdicts: &Verdicts) -> Vec<Bytes> {
265	        let mut out = Vec::new();
266	        for (idx, st) in &mut self.choices {
267	            let Some(v) = verdicts.get(&HoldKey::Choice(*idx)) else { continue };
268	            if st.hold_open && v.blocks_any() && !st.notice_done {
269	                st.notice_done = true;
270	                out.push(notice_chunk(&self.meta, *idx, &st.notice_text(v)));
271	            }
272	        }
273	        out
274	    }
275	
276	    fn known_calls(&self, hold: HoldKey) -> Vec<(u32, String)> {
277	        match hold {
278	            HoldKey::Choice(c) => self.choices.get(&c).map(ChoiceState::known).unwrap_or_default(),
279	            HoldKey::Block(_) => Vec::new(),
280	        }
281	    }
282	
283	    fn unframed(&self, rec: Record) -> Bytes {
284	        sse::frame(None, &rec.data)
285	    }
286	
287	    #[cfg(test)]
288	    fn retained(&self) -> usize {
289	        self.choices.values().map(|s| s.asm.retained()).sum()
290	    }
291	}
292	
293	/// Rewrite one choice entry in place (§ 4.4). Returns the notice text when this entry carries the
294	/// choice's `finish_reason` and the notice is still owed.
295	fn rewrite_choice(ch: &mut Value, verdict: &Verdict, st: &mut ChoiceState) -> Option<String> {
296	    let slots: Vec<u32> = st.known().iter().map(|(p, _)| *p).collect();
297	    let slot_of = |pos: u32| slots.iter().position(|p| *p == pos).unwrap_or(slots.len());
298	    let rank = |pos: u32| -> u32 { u32::try_from((0..slot_of(pos)).filter(|s| verdict.block_code(*s).is_none()).count()).expect("at most 128 calls per choice") };
299	    if let Some(Value::Object(delta)) = ch.get_mut("delta") {
300	        if let Some(Value::Array(tc)) = delta.get_mut("tool_calls") {
301	            tc.retain_mut(|e| {
302	                let pos = e.get("index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok()).unwrap_or(0);
303	                if verdict.block_code(slot_of(pos)).is_some() {
304	                    return false;
305	                }
306	                e["index"] = rank(pos).into();
307	                true
308	            });
309	            if tc.is_empty() {
310	                delta.remove("tool_calls");
311	            }
312	        }
313	        if delta.contains_key("function_call") && verdict.block_code(0).is_some() {
314	            delta.remove("function_call");
315	        }
316	    }
317	    if let Value::Object(o) = ch {
318	        o.remove("logprobs");
319	    }
320	    let finish = ch.get("finish_reason").and_then(Value::as_str).map(str::to_owned)?;
321	    if st.allowed_left(verdict) == 0 && (finish == "tool_calls" || finish == "function_call") {
322	        ch["finish_reason"] = "stop".into();
323	    }
324	    if st.notice_done {
325	        return None;
326	    }
327	    st.notice_done = true;
328	    Some(st.notice_text(verdict))
329	}
