339	    fn rec(s: &str) -> Record {
340	        Record {
341	            event: None,
342	            data: s.as_bytes().to_vec(),
343	        }
344	    }
345	    fn chunk(choices: Value) -> String {
346	        json!({"id":"chatcmpl-1","object":"chat.completion.chunk","created":1,"model":"m","system_fingerprint":"fp","choices":choices}).to_string()
347	    }
