349	    /// Steps every record, then releases every frame under `verdict` for each completed hold.
350	    /// Returns the concatenated output and the completed calls.
351	    fn run(records: &[String], verdict: impl Fn(&[crate::types::ToolCall]) -> Verdict) -> (String, Vec<crate::types::ToolCall>) {
352	        let mut p = OpenAiStream::default();
353	        let mut verdicts = Verdicts::new();
354	        let mut frames = Vec::new();
355	        let mut calls = Vec::new();
356	        for r in records {
357	            match p.step(rec(r), &verdicts).ok().expect("canonical record") {
358	                Step::Frame { frame, completed, .. } => {
359	                    for (k, c) in completed {
360	                        verdicts.insert(k, verdict(&c));
361	                        calls.extend(c);
362	                    }
363	                    frames.push(frame);
364	                }
365	                Step::End(f) | Step::UpstreamError(f) => frames.push(f),
366	            }
367	        }
368	        let mut out = Vec::new();
369	        for f in frames {
370	            for b in p.release(f, &verdicts) {
371	                out.extend_from_slice(&b);
372	            }
373	        }
374	        for b in p.closing(&verdicts) {
375	            out.extend_from_slice(&b);
376	        }
377	        (String::from_utf8(out).unwrap(), calls)
378	    }
