1	// SPDX-License-Identifier: Apache-2.0
2	//! Grammar-based generators of hostile upstream streams (spec § 8.1).
3	//!
4	//! Hidden calls, the ones a correct interceptor must never let through, are named `blocked_*` and
5	//! carry `CANARY` in their arguments. Allowed calls never contain `CANARY`.
6	
7	use proptest::prelude::*;
8	use serde_json::{Value, json};
9	
10	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
11	pub enum Quirk {
12	    DuplicateDelta,
13	    CaseFoldedKey,
14	    ProtoKey,
15	    FloatIndex,
16	    BoolIndex,
17	    NegativeIndex,
18	    RepeatedName,
19	    Bom,
20	    LaxLine,
21	    UnknownFields,
22	    AfterDone,
23	    NoFinalBlank,
24	    Oversized,
25	    NaNRecord,
26	    JsonBody,
27	    EventLine,
28	    IndexGap,
29	    Comments,
30	    Interleave,
31	    EscapedKey,
32	    /// A tool-bearing chunk without `"object":"chat.completion.chunk"` (openai-python skips it).
33	    DropObject,
34	    /// Two choices' records merged into one chunk, the later choice first (LangChain reads
35	    /// `choices[0]` only).
36	    MultiChoiceChunk,
37	    /// One call of choice 0 gets `type: "web_search"` with its `function` body kept.
38	    UnknownType,
39	    /// One chunk names choice 0 twice.
40	    DuplicateChoiceIndex,
41	    /// The choices are rendered in reverse order, so choice 1 appears first (P-10).
42	    ReverseChoices,
43	    /// One function or legacy call of choice 0 loses the last character of its arguments, so they
44	    /// are not one complete JSON value (`incomplete_arguments`).
45	    TruncatedArgs,
46	    /// One function or legacy call of choice 0 gets two JSON objects as arguments (`{..}{"b":2}`).
47	    ConcatenatedObjects,
48	    /// Every call's arguments gain PascalCase, `constructor` and `prototype` keys. They are
49	    /// application data, so the stream is conforming (I-1).
50	    CapitalisedArgKeys,
51	}
52	
53	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
54	pub enum CallKind {
55	    Function,
56	    Custom,
57	    Legacy,
58	}
59	
60	#[derive(Debug, Clone)]
61	pub struct Call {
62	    pub name: &'static str,
63	    pub args: String,
64	    pub kind: CallKind,
65	    pub pieces: usize,
66	}
67	
68	#[derive(Debug, Clone)]
69	pub struct Choice {
70	    pub before: Option<String>,
71	    pub calls: Vec<Call>,
72	    pub after: Option<String>,
73	}
74	
75	#[derive(Debug, Clone)]
76	pub struct Scenario {
77	    pub choices: Vec<Choice>,
78	    pub quirks: Vec<(Quirk, usize)>,
79	    pub cuts: Vec<usize>,
80	}
81	
82	const ALLOWED: [&str; 2] = ["read_file", "send_mail"];
83	const BLOCKED: [&str; 2] = ["blocked_rm", "blocked_exfil"];
84	
85	fn call_strategy() -> impl Strategy<Value = Call> {
86	    (prop::bool::ANY, 0usize..2, "[a-z]{0,12}", 1usize..4, 0u8..10).prop_map(|(blocked, n, s, pieces, k)| {
87	        let name = if blocked { BLOCKED[n] } else { ALLOWED[n] };
88	        let args = if blocked { format!("{{\"v\":\"CANARY-{s}\"}}") } else { format!("{{\"v\":\"{s}\"}}") };
89	        let kind = match k {
90	            0 => CallKind::Custom,
91	            1 | 2 => CallKind::Legacy,
92	            _ => CallKind::Function,
93	        };
94	        Call { name, args, kind, pieces }
95	    })
96	}
97	
98	fn choice_strategy() -> impl Strategy<Value = Choice> {
99	    (prop::option::of("[a-zA-Z ]{1,10}"), prop::collection::vec(call_strategy(), 0..4), prop::option::of("[a-z ]{1,8}")).prop_map(|(before, mut calls, after)| {
100	        if calls.len() > 1 {
101	            for c in &mut calls {
102	                if c.kind == CallKind::Legacy {
103	                    c.kind = CallKind::Function; // a legacy call is the only call of its choice
104	                }
105	            }
106	        }
107	        Choice { before, calls, after }
108	    })
109	}
110	
111	fn quirk_strategy() -> impl Strategy<Value = Quirk> {
112	    prop_oneof![
113	        Just(Quirk::DuplicateDelta),
114	        Just(Quirk::CaseFoldedKey),
115	        Just(Quirk::ProtoKey),
116	        Just(Quirk::FloatIndex),
117	        Just(Quirk::BoolIndex),
118	        Just(Quirk::NegativeIndex),
119	        Just(Quirk::RepeatedName),
120	        Just(Quirk::Bom),
121	        Just(Quirk::LaxLine),
122	        Just(Quirk::UnknownFields),
123	        Just(Quirk::AfterDone),
124	        Just(Quirk::NoFinalBlank),
125	        Just(Quirk::Oversized),
126	        Just(Quirk::NaNRecord),
127	        Just(Quirk::JsonBody),
128	        Just(Quirk::EventLine),
129	        Just(Quirk::IndexGap),
130	        Just(Quirk::Comments),
131	        Just(Quirk::Interleave),
132	        Just(Quirk::EscapedKey),
133	        Just(Quirk::DropObject),
134	        Just(Quirk::MultiChoiceChunk),
135	        Just(Quirk::UnknownType),
136	        Just(Quirk::DuplicateChoiceIndex),
137	        Just(Quirk::ReverseChoices),
138	        Just(Quirk::TruncatedArgs),
139	        Just(Quirk::ConcatenatedObjects),
140	        Just(Quirk::CapitalisedArgKeys),
141	    ]
142	}
143	
144	pub fn openai_scenario() -> impl Strategy<Value = Scenario> {
145	    (
146	        prop::collection::vec(choice_strategy(), 1..3),
147	        prop::collection::vec((quirk_strategy(), 0usize..64), 0..3),
148	        prop::collection::vec(0usize..100_000, 0..6),
149	    )
150	        .prop_map(|(choices, quirks, cuts)| Scenario { choices, quirks, cuts })
151	}
152	
153	fn chunk(choices: Value) -> Value {
154	    json!({"id":"chatcmpl-g","object":"chat.completion.chunk","created":1,"model":"m","choices":choices})
155	}
156	
157	fn hidden_entry(index: Value) -> Value {
158	    json!({"index":index,"id":"call_h","type":"function","function":{"name":"blocked_hidden","arguments":"{\"v\":\"CANARY-hidden\"}"}})
159	}
160	
161	fn split(s: &str, pieces: usize) -> Vec<String> {
162	    let chars: Vec<char> = s.chars().collect();
163	    let step = chars.len().div_ceil(pieces.max(1)).max(1);
164	    chars.chunks(step).map(|c| c.iter().collect()).collect()
165	}
166	
167	fn has(s: &Scenario, q: Quirk) -> Option<usize> {
168	    s.quirks.iter().find(|(x, _)| *x == q).map(|(_, at)| *at)
169	}
170	
171	/// Arguments with keys that the envelope rules would reject (`Id`, `Name`, `constructor`, …).
172	pub fn capitalise_args(args: &str) -> String {
173	    match args.strip_prefix('{') {
174	        Some(rest) => format!(r#"{{"Id":1,"Name":"n","constructor":{{"Type":"t"}},"prototype":[],{rest}"#),
175	        None => args.to_owned(),
176	    }
177	}
178	
179	/// The chunks of one choice. The first chunk carries `role` (openai-node's `finalChatCompletion`
180	/// raises without one), as every real upstream sends it.
181	fn choice_records(c: usize, ch: &Choice, interleave: bool, unknown_type: Option<usize>, bad_args: Option<(Quirk, usize)>, capitalise: bool) -> Vec<Value> {
182	    let mut out = vec![chunk(json!([{"index":c,"delta":{"role":"assistant","content":ch.before.clone().unwrap_or_default()}}]))];
183	    let odd_call = unknown_type.filter(|_| c == 0 && !ch.calls.is_empty()).map(|k| k % ch.calls.len());
184	    let json_calls: Vec<usize> = (0..ch.calls.len()).filter(|i| ch.calls[*i].kind != CallKind::Custom).collect();
185	    let bad = bad_args.filter(|_| c == 0 && !json_calls.is_empty()).map(|(q, k)| (q, json_calls[k % json_calls.len()]));
186	    // Fragments per call: the first carries id/type/name.
187	    let per_call: Vec<Vec<Value>> = ch
188	        .calls
189	        .iter()
190	        .enumerate()
191	        .map(|(i, call)| {
192	            let ty = if odd_call == Some(i) {
193	                "web_search"
194	            } else if call.kind == CallKind::Custom {
195	                "custom"
196	            } else {
197	                "function"
198	            };
199	            let (body, args_key) = if call.kind == CallKind::Custom { ("custom", "input") } else { ("function", "arguments") };
200	            let args = if capitalise { capitalise_args(&call.args) } else { call.args.clone() };
201	            let args = match bad {
202	                Some((Quirk::TruncatedArgs, b)) if b == i => args[..args.len() - 1].to_owned(),
203	                Some((Quirk::ConcatenatedObjects, b)) if b == i => format!("{args}{{\"b\":2}}"),
204	                _ => args,
205	            };
206	            split(&args, call.pieces)
207	                .into_iter()
208	                .enumerate()
209	                .map(|(k, piece)| {
210	                    let delta = if call.kind == CallKind::Legacy {
211	                        if k == 0 {
212	                            json!({"function_call":{"name":call.name,"arguments":piece}})
213	                        } else {
214	                            json!({"function_call":{"arguments":piece}})
215	                        }
216	                    } else if k == 0 {
217	                        json!({"tool_calls":[{"index":i,"id":format!("call_{c}_{i}"),"type":ty,body:{"name":call.name,args_key:piece}}]})
218	                    } else {
219	                        json!({"tool_calls":[{"index":i,body:{args_key:piece}}]})
220	                    };
221	                    chunk(json!([{"index":c,"delta":delta}]))
222	                })
223	                .collect()
224	        })
225	        .collect();
226	    if interleave {
227	        let longest = per_call.iter().map(Vec::len).max().unwrap_or(0);
228	        for k in 0..longest {
229	            for frags in &per_call {
230	                if let Some(f) = frags.get(k) {
231	                    out.push(f.clone());
232	                }
233	            }
234	        }
235	    } else {
236	        out.extend(per_call.into_iter().flatten());
237	    }
238	    if let Some(t) = &ch.after {
239	        out.push(chunk(json!([{"index":c,"delta":{"content":t}}])));
240	    }
241	    let finish = if ch.calls.iter().any(|c| c.kind == CallKind::Legacy) {
242	        "function_call"
243	    } else if ch.calls.is_empty() {
244	        "stop"
245	    } else {
246	        "tool_calls"
247	    };
248	    out.push(chunk(json!([{"index":c,"delta":{},"finish_reason":finish}])));
249	    out
250	}
251	
252	fn choice_of(rec: &Value) -> Option<u64> {
253	    rec.pointer("/choices/0/index").and_then(Value::as_u64)
254	}
255	
256	fn is_tool_bearing(rec: &Value) -> bool {
257	    rec.get("choices")
258	        .and_then(Value::as_array)
259	        .is_some_and(|cs| cs.iter().any(|c| c.pointer("/delta/tool_calls").is_some() || c.pointer("/delta/function_call").is_some()))
260	}
261	
262	pub fn render_openai(s: &Scenario) -> Vec<u8> {
263	    let interleave = has(s, Quirk::Interleave).is_some();
264	    let bad_args = s.quirks.iter().copied().find(|(q, _)| matches!(q, Quirk::TruncatedArgs | Quirk::ConcatenatedObjects));
265	    let mut per: Vec<Vec<Value>> = s
266	        .choices
267	        .iter()
268	        .enumerate()
269	        .map(|(i, c)| choice_records(i, c, interleave, has(s, Quirk::UnknownType), bad_args, has(s, Quirk::CapitalisedArgKeys).is_some()))
270	        .collect();
271	    if has(s, Quirk::ReverseChoices).is_some() {
272	        per.reverse();
273	    }
274	    let mut recs: Vec<Value> = Vec::new();
275	    if interleave {
276	        let longest = per.iter().map(Vec::len).max().unwrap_or(0);
277	        for k in 0..longest {
278	            for p in &per {
279	                if let Some(r) = p.get(k) {
280	                    recs.push(r.clone());
281	                }
282	            }
283	        }
284	    } else {
285	        recs = per.into_iter().flatten().collect();
286	    }
287	    if let Some(at) = has(s, Quirk::MultiChoiceChunk) {
288	        // Merge record p with the first later record of another choice, that choice first.
289	        let p = at % recs.len();
290	        if let Some(q) = (p + 1..recs.len()).find(|q| choice_of(&recs[*q]) != choice_of(&recs[p])) {
291	            let later = recs.remove(q);
292	            let mut both = later["choices"].as_array().cloned().unwrap_or_default();
293	            both.extend(recs[p]["choices"].as_array().cloned().unwrap_or_default());
294	            recs[p]["choices"] = Value::Array(both);
295	        }
296	    }
297	    if let Some(at) = has(s, Quirk::DropObject) {
298	        let tool: Vec<usize> = (0..recs.len()).filter(|i| is_tool_bearing(&recs[*i])).collect();
299	        let i = if tool.is_empty() { at % recs.len() } else { tool[at % tool.len()] };
300	        if let Value::Object(m) = &mut recs[i] {
301	            m.remove("object");
302	        }
303	    }
304	    let mut lines: Vec<String> = recs.iter().map(|r| format!("data: {r}\n\n")).collect();
305	    let mut prefix = String::new();
306	    let mut suffix = String::new();
307	    for (q, at) in &s.quirks {
308	        let pos = at % (lines.len() + 1);
309	        let insert = |lines: &mut Vec<String>, rec: String| lines.insert(pos, format!("data: {rec}\n\n"));
310	        match q {
311	            Quirk::DuplicateDelta => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}},"delta":{{"content":"x"}}}}]}}"#, hidden_entry(json!(0)))),
312	            Quirk::CaseFoldedKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"Tool_Calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
313	            Quirk::ProtoKey => insert(&mut lines, format!(r#"{{"choices":[{{"index":0,"delta":{{"__proto__":{{"tool_calls":[{}]}}}}}}]}}"#, hidden_entry(json!(0)))),
314	            Quirk::FloatIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0.0))]}}])).to_string()),
315	            Quirk::BoolIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(true))]}}])).to_string()),
316	            Quirk::NegativeIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(-1))]}}])).to_string()),
317	            Quirk::RepeatedName => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"name":"blocked_hidden","arguments":"CANARY-rn"}}]}}])).to_string()),
318	            Quirk::IndexGap => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(9))]}}])).to_string()),
319	            Quirk::NaNRecord => insert(&mut lines, format!(r#"{{"x":NaN,"choices":[{{"index":0,"delta":{{"tool_calls":[{}]}}}}]}}"#, hidden_entry(json!(0)))),
320	            Quirk::EscapedKey => insert(
321	                &mut lines,
322	                r#"{"object":"chat.completion.chunk","choices":[{"index":0,"delta":{"tool\u005fcalls":[{"index":0,"id":"call_e","type":"function","function":{"name":"blocked_escaped","arguments":"CANARY-esc"}}]}}]}"#.to_owned(),
323	            ),
324	            Quirk::Oversized => insert(&mut lines, chunk(json!([{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":format!("CANARY-big{}", "x".repeat(5000))}}]}}])).to_string()),
325	            Quirk::DuplicateChoiceIndex => insert(&mut lines, chunk(json!([{"index":0,"delta":{"content":"x"}},{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])).to_string()),
326	            Quirk::LaxLine => lines.insert(
327	                pos,
328	                format!(
329	                    "  data: {}\n\nData: {}\n\n",
330	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}])),
331	                    chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))
332	                ),
333	            ),
334	            Quirk::UnknownFields => lines.insert(pos, "id: 7\nretry: 10\nfoo: bar\n".to_owned()),
335	            Quirk::Comments => lines.insert(pos, ": hello\n: data: {\"x\":\"CANARY-comment\"}\n".to_owned()),
336	            Quirk::EventLine => lines.insert(pos, "event: message\n".to_owned()),
337	            Quirk::Bom => prefix = "\u{feff}".to_owned(),
338	            Quirk::AfterDone => suffix = format!("data: {}\n\n", chunk(json!([{"index":0,"delta":{"tool_calls":[hidden_entry(json!(0))]}}]))),
339	            Quirk::NoFinalBlank | Quirk::JsonBody | Quirk::Interleave | Quirk::DropObject | Quirk::MultiChoiceChunk | Quirk::UnknownType | Quirk::ReverseChoices | Quirk::TruncatedArgs | Quirk::ConcatenatedObjects | Quirk::CapitalisedArgKeys => {}
340	        }
341	    }
342	    let mut body = format!("{prefix}{}data: [DONE]\n\n{suffix}", lines.concat());
343	    if has(s, Quirk::NoFinalBlank).is_some() {
344	        body.truncate(body.trim_end_matches('\n').len());
345	    }
346	    if has(s, Quirk::JsonBody).is_some() {
347	        body = json!({"choices":[{"index":0,"message":{"tool_calls":[{"id":"c","type":"function","function":{"name":"blocked_json","arguments":"CANARY-json"}}]}}]}).to_string();
348	    }
349	    body.into_bytes()
350	}
351	
352	#[derive(Debug, Clone)]
353	pub enum Block {
354	    Text(String),
355	    Tool { name: &'static str, args: String, pieces: usize },
356	    Server,
357	}
358	
359	#[derive(Debug, Clone)]
360	pub struct AnthropicScenario {
361	    pub blocks: Vec<Block>,
362	    pub quirks: Vec<(AQuirk, usize)>,
363	    pub cuts: Vec<usize>,
364	}
365	
366	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
367	pub enum AQuirk {
368	    EventMismatch,
369	    PrefilledInput,
370	    PrefilledMessage,
371	    IndexReuse,
372	    NoEventLines,
373	    Bom,
374	    AfterStop,
375	    DuplicateKey,
376	    Oversized,
377	    /// The next block starts before the previous one stops (`block_interleave`).
378	    Interleave,
379	    /// A tool's last argument piece is lost, so its JSON is incomplete (`incomplete_arguments`).
380	    TruncatedArgs,
381	    /// A delta with index -1 (anthropic-python's `content[-1]` is the last block).
382	    NegativeIndex,
383	    /// A delta for a block after its stop.
384	    DeltaAfterStop,
385	    /// Every tool's input gains PascalCase, `constructor` and `prototype` keys (application data,
386	    /// so conforming; I-1).
387	    CapitalisedArgKeys,
388	}
389	
390	pub fn anthropic_scenario() -> impl Strategy<Value = AnthropicScenario> {
391	    let block = prop_oneof![
392	        "[a-z ]{1,10}".prop_map(Block::Text),
393	        (prop::bool::ANY, 0usize..2, "[a-z]{0,10}", 1usize..4).prop_map(|(b, n, s, pieces)| if b {
394	            Block::Tool {
395	                name: BLOCKED[n],
396	                args: format!("{{\"v\":\"CANARY-{s}\"}}"),
397	                pieces,
398	            }
399	        } else {
400	            Block::Tool {
401	                name: ALLOWED[n],
402	                args: format!("{{\"v\":\"{s}\"}}"),
403	                pieces,
404	            }
405	        }),
406	        Just(Block::Server),
407	    ];
408	    let quirk = prop_oneof![
409	        Just(AQuirk::EventMismatch),
410	        Just(AQuirk::PrefilledInput),
411	        Just(AQuirk::PrefilledMessage),
412	        Just(AQuirk::IndexReuse),
413	        Just(AQuirk::NoEventLines),
414	        Just(AQuirk::Bom),
415	        Just(AQuirk::AfterStop),
416	        Just(AQuirk::DuplicateKey),
417	        Just(AQuirk::Oversized),
418	        Just(AQuirk::Interleave),
419	        Just(AQuirk::TruncatedArgs),
420	        Just(AQuirk::NegativeIndex),
421	        Just(AQuirk::DeltaAfterStop),
422	        Just(AQuirk::CapitalisedArgKeys),
423	    ];
424	    (
425	        prop::collection::vec(block, 0..5),
426	        prop::collection::vec((quirk, 0usize..64), 0..3),
427	        prop::collection::vec(0usize..100_000, 0..6),
428	    )
429	        .prop_map(|(blocks, quirks, cuts)| AnthropicScenario { blocks, quirks, cuts })
430	}
431	
432	fn ahas(s: &AnthropicScenario, q: AQuirk) -> Option<usize> {
433	    s.quirks.iter().find(|(x, _)| *x == q).map(|(_, at)| *at)
434	}
435	
436	pub fn render_anthropic(s: &AnthropicScenario) -> Vec<u8> {
437	    let mut evs: Vec<Value> = vec![json!({"type":"message_start","message":{"id":"msg_g","type":"message","role":"assistant","content":[],"model":"c","usage":{"input_tokens":1,"output_tokens":1}}})];
438	    let tools: Vec<usize> = s.blocks.iter().enumerate().filter(|(_, b)| matches!(b, Block::Tool { .. })).map(|(i, _)| i).collect();
439	    let truncated = ahas(s, AQuirk::TruncatedArgs).filter(|_| !tools.is_empty()).map(|k| tools[k % tools.len()]);
440	    // With Interleave, block k's stop is deferred until after block k+1's start.
441	    let interleave_at = ahas(s, AQuirk::Interleave).filter(|_| s.blocks.len() > 1).map(|k| k % (s.blocks.len() - 1));
442	    let mut deferred: Option<Value> = None;
443	    for (i, b) in s.blocks.iter().enumerate() {
444	        match b {
445	            Block::Text(t) => {
446	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"text","text":""}}));
447	                if let Some(d) = deferred.take() {
448	                    evs.push(d);
449	                }
450	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"text_delta","text":t}}));
451	            }
452	            Block::Tool { name, args, pieces } => {
453	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"tool_use","id":format!("toolu_{i}"),"name":name,"input":{}}}));
454	                if let Some(d) = deferred.take() {
455	                    evs.push(d);
456	                }
457	                let args = if ahas(s, AQuirk::CapitalisedArgKeys).is_some() { capitalise_args(args) } else { args.clone() };
458	                let mut parts = split(&args, *pieces);
459	                if truncated == Some(i) {
460	                    let last = parts.pop().unwrap_or_default();
461	                    parts.push(last[..last.len().saturating_sub(1)].to_owned());
462	                }
463	                for p in parts {
464	                    evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":p}}));
465	                }
466	            }
467	            Block::Server => {
468	                evs.push(json!({"type":"content_block_start","index":i,"content_block":{"type":"server_tool_use","id":format!("srv_{i}"),"name":"web_search","input":{}}}));
469	                if let Some(d) = deferred.take() {
470	                    evs.push(d);
471	                }
472	                evs.push(json!({"type":"content_block_delta","index":i,"delta":{"type":"input_json_delta","partial_json":"{\"q\":\"x\"}"}}));
473	            }
474	        }
475	        let stop = json!({"type":"content_block_stop","index":i});
476	        if interleave_at == Some(i) {
477	            deferred = Some(stop);
478	        } else {
479	            evs.push(stop);
480	        }
481	    }
482	    let any_tool = !tools.is_empty();
483	    evs.push(json!({"type":"message_delta","delta":{"stop_reason": if any_tool { "tool_use" } else { "end_turn" },"stop_sequence":null},"usage":{"output_tokens":1}}));
484	    evs.push(json!({"type":"message_stop"}));
485	    let no_events = ahas(s, AQuirk::NoEventLines).is_some();
486	    let mut frames: Vec<String> = evs
487	        .iter()
488	        .map(|e| {
489	            if no_events {
490	                format!("data: {e}\n\n")
491	            } else {
492	                format!("event: {}\ndata: {e}\n\n", e["type"].as_str().unwrap())
493	            }
494	        })
495	        .collect();
496	    let hidden_start = |idx: usize, input: Value| json!({"type":"content_block_start","index":idx,"content_block":{"type":"tool_use","id":"toolu_h","name":"blocked_hidden","input":input}});
497	    let mut prefix = String::new();
498	    let mut suffix = String::new();
499	    for (q, at) in &s.quirks {
500	        let pos = 1 + at % frames.len().max(1);
501	        let pos = pos.min(frames.len().saturating_sub(1));
502	        match q {
503	            AQuirk::EventMismatch => frames.insert(pos, format!("event: ping\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-em"})))),
504	            AQuirk::PrefilledInput => frames.insert(pos, format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({"v":"CANARY-pi"})))),
505	            AQuirk::PrefilledMessage => {
506	                frames[0] = format!(
507	                    "event: message_start\ndata: {}\n\n",
508	                    json!({"type":"message_start","message":{"content":[{"type":"tool_use","id":"t","name":"blocked_hidden","input":{"v":"CANARY-pm"}}]}})
509	                )
510	            }
511	            AQuirk::IndexReuse => frames.insert(
512	                pos,
513	                format!(
514	                    "event: content_block_start\ndata: {}\n\n",
515	                    json!({"type":"content_block_start","index":0,"content_block":{"type":"tool_use","id":"toolu_r","name":"blocked_reuse","input":{}}})
516	                ),
517	            ),
518	            AQuirk::DuplicateKey => frames.insert(
519	                pos,
520	                format!(
521	                    "event: content_block_delta\ndata: {}\n\n",
522	                    r#"{"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"CANARY-dup"},"delta":{"type":"text_delta","text":"x"}}"#
523	                ),
524	            ),
525	            AQuirk::Oversized => frames.insert(
526	                pos,
527	                format!(
528	                    "event: content_block_delta\ndata: {}\n\n",
529	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":format!("CANARY-big{}", "x".repeat(5000))}})
530	                ),
531	            ),
532	            AQuirk::NegativeIndex => frames.insert(
533	                pos,
534	                format!(
535	                    "event: content_block_delta\ndata: {}\n\n",
536	                    json!({"type":"content_block_delta","index":-1,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-neg\""}})
537	                ),
538	            ),
539	            AQuirk::DeltaAfterStop => frames.insert(
540	                frames.len().saturating_sub(2).max(1),
541	                format!(
542	                    "event: content_block_delta\ndata: {}\n\n",
543	                    json!({"type":"content_block_delta","index":0,"delta":{"type":"input_json_delta","partial_json":"\"CANARY-late\""}})
544	                ),
545	            ),
546	            AQuirk::Bom => prefix = "\u{feff}".to_owned(),
547	            AQuirk::AfterStop => suffix = format!("event: content_block_start\ndata: {}\n\n", hidden_start(s.blocks.len(), json!({}))),
548	            AQuirk::NoEventLines | AQuirk::Interleave | AQuirk::TruncatedArgs | AQuirk::CapitalisedArgKeys => {}
549	        }
550	    }
551	    format!("{prefix}{}{suffix}", frames.concat()).into_bytes()
552	}
