70	pub struct Interceptor {
71	    proto: Box<dyn Protocol>,
72	    sse: SseSplitter,
73	    limits: Limits,
74	    terminal: Bytes,
75	    queue: VecDeque<Frame>,
76	    queued: usize,
77	    verdicts: Verdicts,
78	    holds: BTreeMap<HoldKey, Track>,
79	    mode: Mode,
80	    after_end: bool,
81	    input_done: bool,
82	    ended: bool,
83	    last_emit: Instant,
84	    out: Vec<Action>,
85	}
