94	impl Interceptor {
95	    #[must_use]
96	    pub fn new(format: Format, limits: Limits, terminal: Bytes, now: Instant) -> Self {
97	        let proto: Box<dyn Protocol> = match format {
98	            Format::OpenAiChat => Box::new(OpenAiStream::with_cap(limits.max_held_bytes)),
99	            Format::AnthropicMessages => Box::new(AnthropicStream::with_cap(limits.max_held_bytes)),
100	        };
101	        Interceptor {
102	            proto,
103	            sse: SseSplitter::new(limits.max_record_bytes),
104	            limits,
105	            terminal,
106	            queue: VecDeque::new(),
107	            queued: 0,
108	            verdicts: Verdicts::new(),
109	            holds: BTreeMap::new(),
110	            mode: Mode::Normal,
111	            after_end: false,
112	            input_done: false,
113	            ended: false,
114	            last_emit: now,
115	            out: Vec::new(),
116	        }
117	    }
118	
119	    /// Feed upstream bytes.
120	    pub fn push(&mut self, chunk: &[u8], now: Instant) -> Vec<Action> {
121	        if self.ended || self.input_done {
122	            return Vec::new();
123	        }
124	        for item in self.sse.push(chunk) {
125	            self.item(item, now);
126	            if self.ended {
127	                break;
128	            }
129	        }
130	        self.settle(now)
131	    }
132	
133	    /// The upstream ended cleanly. The stream ends once nothing is queued or deciding.
134	    pub fn finish(&mut self, now: Instant) -> Vec<Action> {
135	        if self.ended || self.input_done {
136	            return Vec::new();
137	        }
138	        for item in self.sse.finish() {
139	            self.item(item, now);
140	            if self.ended {
141	                break;
142	            }
143	        }
144	        self.input_done = true;
145	        if !self.ended {
146	            self.truncate_open();
147	        }
148	        self.settle(now)
149	    }
150	
151	    /// The upstream failed (D17): drop the queue, emit the terminal frame, and end.
152	    pub fn abort(&mut self) -> Vec<Action> {
153	        if self.ended {
154	            return Vec::new();
155	        }
156	        self.queue.clear();
157	        self.queued = 0;
158	        self.ended = true;
159	        let mut out = std::mem::take(&mut self.out);
160	        out.push(Action::Emit(self.terminal.clone()));
161	        out
162	    }
163	
164	    /// The decider's answer for `hold`. An answer for a hold that is no longer deciding is ignored.
165	    pub fn decided(&mut self, hold: HoldKey, result: Result<Vec<Decision>, DeciderError>, now: Instant) -> Vec<Action> {
166	        if self.ended {
167	            return Vec::new();
168	        }
169	        self.apply_decision(hold, result, now);
170	        self.settle(now)
171	    }
172	
173	    /// Enforce the deadlines (D14) and send a keep-alive when one is due (D15).
174	    pub fn tick(&mut self, now: Instant) -> Vec<Action> {
175	        if self.ended {
176	            return Vec::new();
177	        }
178	        let due: Vec<(HoldKey, bool)> = self
179	            .holds
180	            .iter()
181	            .filter_map(|(k, t)| match t {
182	                Track::Assembling { opened, observe: false } if now.saturating_duration_since(*opened) >= self.limits.max_hold => Some((*k, false)),
183	                Track::Deciding { since, .. } if now.saturating_duration_since(*since) >= self.limits.decide_timeout => Some((*k, true)),
184	                _ => None,
185	            })
186	            .collect();
187	        for (k, deciding) in due {
188	            if deciding {
189	                self.apply_decision(k, Err(DeciderError { reason: "timeout" }), now);
190	            } else {
191	                self.count(Metric::OnFailure("hold_limit"));
192	                self.hold_limit(k);
193	            }
194	        }
195	        if self.holding() && now.saturating_duration_since(self.last_emit) >= self.limits.keepalive {
196	            self.emit(Bytes::from_static(sse::KEEP_ALIVE), now);
197	        }
198	        self.settle(now)
199	    }
200	
201	    #[must_use]
202	    pub fn is_finished(&self) -> bool {
203	        self.ended
204	    }
205	
206	    /// Whether `hold` still waits for its decision. The relay drops a decider future whose hold
207	    /// is no longer deciding, for example after a timeout.
208	    #[must_use]
209	    pub fn is_deciding(&self, hold: HoldKey) -> bool {
210	        matches!(self.holds.get(&hold), Some(Track::Deciding { .. }))
211	    }
212	
213	    #[doc(hidden)]
214	    #[must_use]
215	    pub fn queued_bytes(&self) -> usize {
216	        self.queued
217	    }
218	
219	    #[cfg(test)]
220	    fn retained_bytes(&self) -> usize {
221	        self.proto.retained()
222	    }
223	
224	    // ---- input ---------------------------------------------------------------------------------
225	
226	    fn item(&mut self, item: SseItem, now: Instant) {
227	        // D4: after the end marker every record is dropped, an oversized one included. It must not
228	        // become a stream failure that rules on a hold still waiting for the decider.
229	        if self.after_end {
230	            self.count(Metric::RecordDropped("after_done"));
231	            return;
232	        }
233	        let rec = match item {
234	            SseItem::Oversized => {
235	                self.count(Metric::RecordDropped("oversized"));
236	                self.stream_failure(now);
237	                return;
238	            }
239	            SseItem::Record(r) => r,
240	        };
241	        if self.mode == Mode::PassThrough {
242	            let b = self.proto.unframed(rec);
243	            self.emit(b, now);
244	            return;
245	        }
246	        match self.proto.step(rec, &self.verdicts) {
247	            Err(StepError::Malformed) => {
248	                self.count(Metric::RecordDropped("malformed"));
249	                if !self.queue.is_empty() {
250	                    self.stream_failure(now);
251	                }
252	            }
253	            Err(StepError::Deviation(why)) => {
254	                self.count(Metric::RecordDropped(if why == "late_fragment" { "late_fragment" } else { "malformed" }));
255	                self.stream_failure(now);
256	            }
257	            Ok(Step::UpstreamError(frame)) => {
258	                if !self.queue.is_empty() || self.any_open() {
259	                    let acts = self.abort();
260	                    self.out.extend(acts);
261	                } else {
262	                    self.enqueue(frame, now);
263	                }
264	            }
265	            Ok(Step::End(frame)) => {
266	                self.after_end = true;
267	                self.truncate_open();
268	                self.enqueue(frame, now);
269	            }
270	            Ok(Step::Frame { frame, opened, completed, reports }) => {
271	                for r in &reports {
272	                    self.emit(report_comment(r), now);
273	                }
274	                for k in opened {
275	                    self.open(k, now);
276	                }
277	                self.enqueue(frame, now);
278	                for (k, calls) in completed {
279	                    self.complete(k, calls, now);
280	                }
281	            }
282	        }
283	    }
284	
285	    fn open(&mut self, k: HoldKey, now: Instant) {
286	        match self.mode {
287	            Mode::Failed(code) => self.block_all(k, code),
288	            _ => {
289	                self.holds.insert(k, Track::Assembling { opened: now, observe: false });
290	            }
291	        }
292	    }
293	
294	    fn complete(&mut self, k: HoldKey, calls: Vec<ToolCall>, now: Instant) {
295	        if let Some(Track::Assembling { opened, observe }) = self.holds.get(&k).cloned() {
296	            self.count(Metric::HoldSeconds(now.saturating_duration_since(opened).as_secs_f64()));
297	            self.holds.insert(
298	                k,
299	                Track::Deciding {
300	                    since: now,
301	                    calls: calls.clone(),
302	                    observe,
303	                },
304	            );
305	            self.out.push(Action::Decide { hold: k, calls });
306	        }
307	    }
308	
309	    fn enqueue(&mut self, frame: Frame, now: Instant) {
310	        if self.queue.is_empty() && self.releasable(&frame) {
311	            for b in self.proto.release(frame, &self.verdicts) {
312	                self.emit(b, now);
313	            }
314	            return;
315	        }
316	        self.queued += frame.payload.len();
317	        self.queue.push_back(frame);
318	        if self.queued > self.limits.max_held_bytes {
319	            let over = self.undecided();
320	            if !over.is_empty() {
321	                self.count(Metric::OnFailure("hold_limit"));
322	                for k in over {
323	                    self.hold_limit(k);
324	                }
325	            }
326	            // The limited holds have verdicts now; release at once so the queue stays bounded
327	            // within one push.
328	            self.release_ready(now);
329	        }
330	    }
331	
332	    // ---- decisions and failures ----------------------------------------------------------------
333	
334	    fn apply_decision(&mut self, hold: HoldKey, result: Result<Vec<Decision>, DeciderError>, now: Instant) {
335	        let Some(Track::Deciding { calls, observe, .. }) = self.holds.get(&hold).cloned() else { return };
336	        let checked = match result {
337	            Ok(d) if d.len() == calls.len() => Ok(d),
338	            Ok(_) => Err(DeciderError { reason: "wrong_length" }),
339	            Err(e) => Err(e),
340	        };
341	        let (verdict, decisions, mut basis) = match (checked, self.limits.on_failure) {
342	            (Ok(d), _) => {
343	                let v = if d.iter().all(|d| d.is_allow()) { Verdict::AllowAll } else { Verdict::PerCall(d.clone()) };
344	                (v, d, Basis::Decider)
345	            }
346	            (Err(_), OnFailure::Block) => {
347	                self.count(Metric::OnFailure("decider_error"));
348	                (
349	                    Verdict::BlockAll(BlockCode::DeciderError),
350	                    vec![Decision::Block { code: BlockCode::DeciderError }; calls.len()],
351	                    Basis::OnFailure,
352	                )
353	            }
354	            (Err(_), OnFailure::Allow) => {
355	                self.count(Metric::OnFailure("decider_error"));
356	                (Verdict::AllowAll, vec![Decision::Allow; calls.len()], Basis::OnFailure)
357	            }
358	        };
359	        if observe {
360	            basis = Basis::OnFailure;
361	        }
362	        for (c, d) in calls.iter().zip(&decisions) {
363	            let (decision, code) = match d {
364	                Decision::Block { code } => (ReportDecision::Block, Some(*code)),
365	                _ => (ReportDecision::Allow, None),
366	            };
367	            let label = if decision == ReportDecision::Block { "block" } else { "allow" };
368	            self.count(Metric::Decision {
369	                decision: label,
370	                basis: basis.as_str(),
371	            });
372	            let entry = ReportEntry {
373	                choice: c.choice,
374	                position: c.position,
375	                name: c.name.clone(),
376	                decision,
377	                basis: Some(basis),
378	                code,
379	            };
380	            self.emit(report_comment(&entry), now);
381	        }
382	        if !observe {
383	            self.verdicts.insert(hold, verdict);
384	        }
385	        self.holds.insert(hold, Track::Decided);
386	    }
387	
388	    /// D13/D14: one hold over a limit.
389	    fn hold_limit(&mut self, k: HoldKey) {
390	        match self.limits.on_failure {
391	            OnFailure::Block => self.block_all(k, BlockCode::HoldLimit),
392	            OnFailure::Allow => self.observe(k),
393	        }
394	    }
395	
396	    /// A hold blocked as a whole, with one report per call known so far.
397	    fn block_all(&mut self, k: HoldKey, code: BlockCode) {
398	        self.verdicts.insert(k, Verdict::BlockAll(code));
399	        self.holds.insert(k, Track::Decided);
400	        let known = self.proto.known_calls(k);
401	        let known = if known.is_empty() { vec![(0, "unknown".to_owned())] } else { known };
402	        for (position, name) in known {
403	            let entry = ReportEntry {
404	                choice: choice_of(k),
405	                position,
406	                name,
407	                decision: ReportDecision::Block,
408	                basis: Some(Basis::OnFailure),
409	                code: Some(code),
410	            };
411	            self.count(Metric::Decision {
412	                decision: "block",
413	                basis: Basis::OnFailure.as_str(),
414	            });
415	            self.out.push(Action::Emit(report_comment(&entry)));
416	        }
417	    }
418	
419	    /// Observe mode: released as is, still decided for the report once complete (§ 5.3).
420	    fn observe(&mut self, k: HoldKey) {
421	        self.verdicts.insert(k, Verdict::PassThrough);
422	        let next = match self.holds.get(&k) {
423	            Some(Track::Assembling { opened, .. }) => Track::Assembling { opened: *opened, observe: true },
424	            Some(Track::Deciding { since, calls, .. }) => Track::Deciding {
425	                since: *since,
426	                calls: calls.clone(),
427	                observe: true,
428	            },
429	            _ => return,
430	        };
431	        self.holds.insert(k, next);
432	    }
433	
434	    fn stream_failure(&mut self, now: Instant) {
435	        if self.mode != Mode::Normal {
436	            return;
437	        }
438	        self.count(Metric::OnFailure("malformed"));
439	        match self.limits.on_failure {
440	            OnFailure::Block => {
441	                self.mode = Mode::Failed(BlockCode::Malformed);
442	                for k in self.undecided() {
443	                    self.block_all(k, BlockCode::Malformed);
444	                }
445	            }
446	            OnFailure::Allow => {
447	                self.mode = Mode::PassThrough;
448	                for k in self.undecided() {
449	                    self.observe(k);
450	                }
451	                // The queued frames go out before any later record is forwarded unclassified.
452	                self.release_ready(now);
453	                self.emit(sse::comment("paigasus-interception pass-through"), now);
454	            }
455	        }
456	    }
457	
458	    /// D10/D11: the stream ended with these holds still assembling.
459	    fn truncate_open(&mut self) {
460	        for k in self.proto.incomplete() {
461	            match self.holds.get(&k) {
462	                Some(Track::Assembling { observe: false, .. }) => {
463	                    self.count(Metric::OnFailure("truncated"));
464	                    match self.limits.on_failure {
465	                        OnFailure::Block => self.block_all(k, BlockCode::Truncated),
466	                        OnFailure::Allow => {
467	                            self.verdicts.insert(k, Verdict::PassThrough);
468	                            self.holds.insert(k, Track::Decided);
469	                        }
470	                    }
471	                }
472	                Some(Track::Assembling { observe: true, .. }) => {
473	                    self.holds.insert(k, Track::Decided);
474	                }
475	                _ => {}
476	            }
477	        }
478	    }
479	
480	    // ---- output --------------------------------------------------------------------------------
481	
482	    /// D12: pop from the head while every hold the head touches has a verdict.
483	    fn release_ready(&mut self, now: Instant) {
484	        while let Some(front) = self.queue.front() {
485	            if !self.releasable(front) {
486	                break;
487	            }
488	            let frame = self.queue.pop_front().expect("front exists");
489	            self.queued -= frame.payload.len();
490	            for b in self.proto.release(frame, &self.verdicts) {
491	                self.emit(b, now);
492	            }
493	        }
494	    }
495	
496	    fn settle(&mut self, now: Instant) -> Vec<Action> {
497	        if !self.ended {
498	            self.release_ready(now);
499	            if self.input_done && self.queue.is_empty() && !self.any_deciding() {
500	                for b in self.proto.closing(&self.verdicts) {
501	                    self.emit(b, now);
502	                }
503	                self.ended = true;
504	            }
505	        }
506	        if !self.ended {
507	            let at = self.next_wake(now);
508	            self.out.push(Action::Wake(at));
509	        }
510	        std::mem::take(&mut self.out)
511	    }
512	
513	    fn releasable(&self, frame: &Frame) -> bool {
514	        frame.touches.iter().all(|k| self.verdicts.contains_key(k))
515	    }
516	
517	    fn emit(&mut self, b: Bytes, now: Instant) {
518	        self.out.push(Action::Emit(b));
519	        self.last_emit = now;
520	    }
521	
522	    fn count(&mut self, m: Metric) {
523	        self.out.push(Action::Count(m));
524	    }
525	
526	    /// The next deadline. With nothing held no keep-alive is owed, so the base moves with `now`
527	    /// and a wake never lies in the past.
528	    fn next_wake(&self, now: Instant) -> Instant {
529	        let mut at = if self.holding() { self.last_emit + self.limits.keepalive } else { now + self.limits.keepalive };
530	        for t in self.holds.values() {
531	            let d = match t {
532	                Track::Assembling { opened, observe: false } => *opened + self.limits.max_hold,
533	                Track::Deciding { since, .. } => *since + self.limits.decide_timeout,
534	                _ => continue,
535	            };
536	            at = at.min(d);
537	        }
538	        at
539	    }
540	
541	    /// D15: a keep-alive is owed while the queue is non-empty or a hold is deciding.
542	    fn holding(&self) -> bool {
543	        !self.queue.is_empty() || self.any_deciding()
544	    }
545	
546	    fn undecided(&self) -> Vec<HoldKey> {
547	        self.holds
548	            .iter()
549	            .filter(|(_, t)| matches!(t, Track::Assembling { observe: false, .. } | Track::Deciding { observe: false, .. }))
550	            .map(|(k, _)| *k)
551	            .collect()
552	    }
553	
554	    fn any_open(&self) -> bool {
555	        self.holds.values().any(|t| matches!(t, Track::Assembling { .. } | Track::Deciding { .. }))
556	    }
557	
558	    fn any_deciding(&self) -> bool {
559	        self.holds.values().any(|t| matches!(t, Track::Deciding { .. }))
560	    }
561	}
