618	    /// Run a whole stream. `decide` answers each Decide at once; `None` leaves it pending.
619	    struct Run {
620	        out: String,
621	        decides: Vec<(HoldKey, Vec<ToolCall>)>,
622	        counts: Vec<Metric>,
623	    }
624	    type Decider<'a> = dyn Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> + 'a;
625	    fn run_format(format: Format, limits: Limits, chunks: &[String], decide: &Decider<'_>) -> (Run, Interceptor) {
626	        let t0 = Instant::now();
627	        let mut i = Interceptor::new(format, limits, Bytes::from_static(TERMINAL), t0);
628	        let mut r = Run {
629	            out: String::new(),
630	            decides: Vec::new(),
631	            counts: Vec::new(),
632	        };
633	        let mut pending: Vec<Action> = Vec::new();
634	        for c in chunks {
635	            pending.extend(i.push(c.as_bytes(), t0));
636	            drain(&mut i, &mut pending, &mut r, decide, t0);
637	        }
638	        pending.extend(i.finish(t0));
639	        drain(&mut i, &mut pending, &mut r, decide, t0);
640	        (r, i)
641	    }
642	    fn run_with(limits: Limits, chunks: &[String], decide: impl Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>>) -> Run {
643	        run_format(Format::OpenAiChat, limits, chunks, &decide).0
644	    }
645	    fn drain(i: &mut Interceptor, pending: &mut Vec<Action>, r: &mut Run, decide: &Decider<'_>, now: Instant) {
646	        while !pending.is_empty() {
647	            for a in std::mem::take(pending) {
648	                match a {
649	                    Action::Emit(b) => r.out.push_str(std::str::from_utf8(&b).unwrap()),
650	                    Action::Decide { hold, calls } => {
651	                        r.decides.push((hold, calls.clone()));
652	                        if let Some(res) = decide(&calls) {
653	                            pending.extend(i.decided(hold, res, now));
654	                        }
655	                    }
656	                    Action::Count(m) => r.counts.push(m),
657	                    Action::Wake(_) => {}
658	                }
659	            }
660	        }
661	    }
662	    fn allow(c: &[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> {
663	        Some(Ok(vec![Decision::Allow; c.len()]))
664	    }
665	    fn block_named(prefix: &'static str) -> impl Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> {
666	        move |c| {
667	            Some(Ok(c
668	                .iter()
669	                .map(|t| {
670	                    if t.name.starts_with(prefix) {
671	                        Decision::Block { code: BlockCode::Policy }
672	                    } else {
673	                        Decision::Allow
674	                    }
675	                })
676	                .collect()))
677	        }
678	    }
