1060	                    vec![args(0, 0, "\"}"), finish(0)],
1061	                    "data: [DONE]\n\n".into(),
1062	                ),
1063	                Format::AnthropicMessages => (
1064	                    tool_start(0, "write"),
1065	                    Box::new(|| json_delta(0, &piece)),
1066	                    vec![json_delta(0, "\"}"), block_stop(0)],
1067	                    ev(json!({"type":"message_stop"})),
1068	                ),
1069	            };
1070	            let t0 = Instant::now();
1071	            let mut i = Interceptor::new(format, l, Bytes::from_static(TERMINAL), t0);
1072	            let mut acts = i.push(open.as_bytes(), t0);
1073	            if format == Format::AnthropicMessages {
1074	                acts.extend(i.push(json_delta(0, "{\"a\":\"").as_bytes(), t0));
1075	            }
1076	            for _ in 0..200 {
