618	    /// Run a whole stream. `decide` answers each Decide at once; `None` leaves it pending.
619	    struct Run {
620	        out: String,
621	        decides: Vec<(HoldKey, Vec<ToolCall>)>,
622	        counts: Vec<Metric>,
623	    }
624	    type Decider<'a> = dyn Fn(&[ToolCall]) -> Option<Result<Vec<Decision>, DeciderError>> + 'a;
625	    fn run_format(format: Format, limits: Limits, chunks: &[String], decide: &Decider<'_>) -> (Run, Interceptor) {
626	        let t0 = Instant::now();
627	        let mut i = Interceptor::new(format, limits, Bytes::from_static(TERMINAL), t0);
628	        let mut r = Run {
629	            out: String::new(),
630	            decides: Vec::new(),
631	            counts: Vec::new(),
632	        };
633	        let mut pending: Vec<Action> = Vec::new();
634	        for c in chunks {
635	            pending.extend(i.push(c.as_bytes(), t0));
636	            drain(&mut i, &mut pending, &mut r, decide, t0);
637	        }
638	        pending.extend(i.finish(t0));
639	        drain(&mut i, &mut pending, &mut r, decide, t0);
640	        (r, i)
641	    }
